window.NAWAWI=["\u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u0650\u064a\u0631\u0650 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064e\u0628\u0650\u064a \u062d\u064e\u0641\u0652\u0635\u064d \u0639\u064f\u0645\u064e\u0631\u064e \u0628\u0652\u0646\u0650 \u0627\u0644\u0652\u062e\u064e\u0637\u064e\u0651\u0627\u0628\u0650 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0633\u064e\u0645\u0650\u0639\u0652\u062a\u064f \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \" \u0625\u0646\u064e\u0651\u0645\u064e\u0627 \u0627\u0644\u0652\u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f \u0628\u0650\u0627\u0644\u0646\u0650\u0651\u064a\u064e\u0651\u0627\u062a\u0650\u060c \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0645\u064e\u0627 \u0644\u0650\u0643\u064f\u0644\u0650\u0651 \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u064e\u0627 \u0646\u064e\u0648\u064e\u0649\u060c \u0641\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0647\u0650\u062c\u0652\u0631\u064e\u062a\u064f\u0647\u064f \u0625\u0644\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650 \u0641\u064e\u0647\u0650\u062c\u0652\u0631\u064e\u062a\u064f\u0647\u064f \u0625\u0644\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e\u062a\u0652 \u0647\u0650\u062c\u0652\u0631\u064e\u062a\u064f\u0647\u064f \u0644\u0650\u062f\u064f\u0646\u0652\u064a\u064e\u0627 \u064a\u064f\u0635\u0650\u064a\u0628\u064f\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0627\u0645\u0652\u0631\u064e\u0623\u064e\u0629\u064d \u064a\u064e\u0646\u0652\u0643\u0650\u062d\u064f\u0647\u064e\u0627 \u0641\u064e\u0647\u0650\u062c\u0652\u0631\u064e\u062a\u064f\u0647\u064f \u0625\u0644\u064e\u0649 \u0645\u064e\u0627 \u0647\u064e\u0627\u062c\u064e\u0631\u064e \u0625\u0644\u064e\u064a\u0652\u0647\u0650\". \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0625\u0650\u0645\u064e\u0627\u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064f\u062d\u064e\u062f\u0650\u0651\u062b\u0650\u064a\u0646\u064e \u0623\u064e\u0628\u064f\u0648 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u0647\u0650 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064f \u0628\u0646\u064f \u0625\u0650\u0633\u0652\u0645\u064e\u0627\u0639\u0650\u064a\u0644 \u0628\u0646 \u0625\u0650\u0628\u0652\u0631\u064e\u0627\u0647\u0650\u064a\u0645 \u0628\u0646 \u0627\u0644\u0652\u0645\u064f\u063a\u0650\u064a\u0631\u064e\u0629 \u0628\u0646 \u0628\u064e\u0631\u0652\u062f\u0650\u0632\u0628\u064e\u0647 \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651 \u0627\u0644\u0652\u062c\u064f\u0639\u0652\u0641\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:1]\u060c \u0648\u064e\u0623\u064e\u0628\u064f\u0648 \u0627\u0644\u0652\u062d\u064f\u0633\u064e\u064a\u0652\u0646\u0650 \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c \u0628\u0646\u064f \u0627\u0644\u0652\u062d\u064e\u062c\u064e\u0651\u0627\u062c \u0628\u0646 \u0645\u064f\u0633\u0652\u0644\u0650\u0645 \u0627\u0644\u0652\u0642\u064f\u0634\u064e\u064a\u0652\u0631\u0650\u064a\u064f\u0651 \u0627\u0644\u0646\u064e\u0651\u064a\u0652\u0633\u064e\u0627\u0628\u064f\u0648\u0631\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:1907] \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0641\u0650\u064a \"\u0635\u064e\u062d\u0650\u064a\u062d\u064e\u064a\u0652\u0647\u0650\u0645\u064e\u0627\" \u0627\u0644\u0644\u0630\u064e\u064a\u0646\u0650 \u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u062d\u064f\u0651 \u0627\u0644\u0652\u0643\u064f\u062a\u064f\u0628\u0650 \u0627\u0644\u0652\u0645\u064f\u0635\u064e\u0646\u064e\u0651\u0641\u064e\u0629\u0650", "\u0639\u064e\u0646\u0652 \u0639\u064f\u0645\u064e\u0631\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u064a\u0652\u0636\u064b\u0627 \u0642\u064e\u0627\u0644\u064e: \u0628\u064e\u064a\u0652\u0646\u064e\u0645\u064e\u0627 \u0646\u064e\u062d\u0652\u0646\u064f \u062c\u064f\u0644\u064f\u0648\u0633\u064c \u0639\u0650\u0646\u0652\u062f\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0630\u064e\u0627\u062a\u064e \u064a\u064e\u0648\u0652\u0645\u064d\u060c \u0625\u0630\u0652 \u0637\u064e\u0644\u064e\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0646\u064e\u0627 \u0631\u064e\u062c\u064f\u0644\u064c \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0628\u064e\u064a\u064e\u0627\u0636\u0650 \u0627\u0644\u062b\u0650\u0651\u064a\u064e\u0627\u0628\u0650\u060c \u0634\u064e\u062f\u0650\u064a\u062f\u064f \u0633\u064e\u0648\u064e\u0627\u062f\u0650 \u0627\u0644\u0634\u064e\u0651\u0639\u0652\u0631\u0650\u060c \u0644\u064e\u0627 \u064a\u064f\u0631\u064e\u0649 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u062b\u064e\u0631\u064f \u0627\u0644\u0633\u064e\u0651\u0641\u064e\u0631\u0650\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0647\u064f \u0645\u0650\u0646\u064e\u0651\u0627 \u0623\u064e\u062d\u064e\u062f\u064c. \u062d\u064e\u062a\u064e\u0651\u0649 \u062c\u064e\u0644\u064e\u0633\u064e \u0625\u0644\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 . \u0641\u064e\u0623\u064e\u0633\u0652\u0646\u064e\u062f\u064e \u0631\u064f\u0643\u0652\u0628\u064e\u062a\u064e\u064a\u0652\u0647\u0650 \u0625\u0644\u064e\u0649 \u0631\u064f\u0643\u0652\u0628\u064e\u062a\u064e\u064a\u0652\u0647\u0650\u060c \u0648\u064e\u0648\u064e\u0636\u064e\u0639\u064e \u0643\u064e\u0641\u064e\u0651\u064a\u0652\u0647\u0650 \u0639\u064e\u0644\u064e\u0649 \u0641\u064e\u062e\u0650\u0630\u064e\u064a\u0652\u0647\u0650\u060c \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u064a\u064e\u0627 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064f \u0623\u064e\u062e\u0652\u0628\u0650\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650. \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u064f \u0623\u064e\u0646\u0652 \u062a\u064e\u0634\u0652\u0647\u064e\u062f\u064e \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0644\u064e\u0647\u064e \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u062a\u064f\u0642\u0650\u064a\u0645\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064e\u060c \u0648\u064e\u062a\u064f\u0624\u0652\u062a\u0650\u064a\u064e \u0627\u0644\u0632\u064e\u0651\u0643\u064e\u0627\u0629\u064e\u060c \u0648\u064e\u062a\u064e\u0635\u064f\u0648\u0645\u064e \u0631\u064e\u0645\u064e\u0636\u064e\u0627\u0646\u064e\u060c \u0648\u064e\u062a\u064e\u062d\u064f\u062c\u064e\u0651 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e \u0625\u0646\u0652 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a \u0625\u0644\u064e\u064a\u0652\u0647\u0650 \u0633\u064e\u0628\u0650\u064a\u0644\u064b\u0627. \u0642\u064e\u0627\u0644\u064e: \u0635\u064e\u062f\u064e\u0642\u0652\u062a . \u0641\u064e\u0639\u064e\u062c\u0650\u0628\u0652\u0646\u064e\u0627 \u0644\u064e\u0647\u064f \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0647\u064f \u0648\u064e\u064a\u064f\u0635\u064e\u062f\u0650\u0651\u0642\u064f\u0647\u064f! \u0642\u064e\u0627\u0644\u064e: \u0641\u064e\u0623\u064e\u062e\u0652\u0628\u0650\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650. \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0646\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0628\u0650\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0645\u064e\u0644\u064e\u0627\u0626\u0650\u0643\u064e\u062a\u0650\u0647\u0650 \u0648\u064e\u0643\u064f\u062a\u064f\u0628\u0650\u0647\u0650 \u0648\u064e\u0631\u064f\u0633\u064f\u0644\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650\u060c \u0648\u064e\u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064e \u0628\u0650\u0627\u0644\u0652\u0642\u064e\u062f\u064e\u0631\u0650 \u062e\u064e\u064a\u0652\u0631\u0650\u0647\u0650 \u0648\u064e\u0634\u064e\u0631\u0650\u0651\u0647\u0650. \u0642\u064e\u0627\u0644\u064e: \u0635\u064e\u062f\u064e\u0642\u0652\u062a. \u0642\u064e\u0627\u0644\u064e: \u0641\u064e\u0623\u064e\u062e\u0652\u0628\u0650\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0627\u0644\u0652\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u0650. \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0646\u0652 \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0643\u064e\u0623\u064e\u0646\u064e\u0651\u0643 \u062a\u064e\u0631\u064e\u0627\u0647\u064f\u060c \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u062a\u064e\u0643\u064f\u0646\u0652 \u062a\u064e\u0631\u064e\u0627\u0647\u064f \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u064a\u064e\u0631\u064e\u0627\u0643. \u0642\u064e\u0627\u0644\u064e: \u0641\u064e\u0623\u064e\u062e\u0652\u0628\u0650\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0627\u0644\u0633\u064e\u0651\u0627\u0639\u064e\u0629\u0650. \u0642\u064e\u0627\u0644\u064e: \u0645\u064e\u0627 \u0627\u0644\u0652\u0645\u064e\u0633\u0652\u0626\u064f\u0648\u0644\u064f \u0639\u064e\u0646\u0652\u0647\u064e\u0627 \u0628\u0650\u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064e \u0645\u0650\u0646\u0652 \u0627\u0644\u0633\u064e\u0651\u0627\u0626\u0650\u0644\u0650. \u0642\u064e\u0627\u0644\u064e: \u0641\u064e\u0623\u064e\u062e\u0652\u0628\u0650\u0631\u0652\u0646\u0650\u064a \u0639\u064e\u0646\u0652 \u0623\u064e\u0645\u064e\u0627\u0631\u064e\u0627\u062a\u0650\u0647\u064e\u0627\u061f \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0646\u0652 \u062a\u064e\u0644\u0650\u062f\u064e \u0627\u0644\u0652\u0623\u064e\u0645\u064e\u0629\u064f \u0631\u064e\u0628\u064e\u0651\u062a\u064e\u0647\u064e\u0627\u060c \u0648\u064e\u0623\u064e\u0646\u0652 \u062a\u064e\u0631\u064e\u0649 \u0627\u0644\u0652\u062d\u064f\u0641\u064e\u0627\u0629\u064e \u0627\u0644\u0652\u0639\u064f\u0631\u064e\u0627\u0629\u064e \u0627\u0644\u0652\u0639\u064e\u0627\u0644\u064e\u0629\u064e \u0631\u0650\u0639\u064e\u0627\u0621\u064e \u0627\u0644\u0634\u064e\u0651\u0627\u0621\u0650 \u064a\u064e\u062a\u064e\u0637\u064e\u0627\u0648\u064e\u0644\u064f\u0648\u0646\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u0628\u064f\u0646\u0652\u064a\u064e\u0627\u0646\u0650. \u062b\u064f\u0645\u064e\u0651 \u0627\u0646\u0652\u0637\u064e\u0644\u064e\u0642\u064e\u060c \u0641\u064e\u0644\u064e\u0628\u0650\u062b\u0652\u062a\u064f \u0645\u064e\u0644\u0650\u064a\u064b\u0651\u0627\u060c \u062b\u064f\u0645\u064e\u0651 \u0642\u064e\u0627\u0644\u064e: \u064a\u064e\u0627 \u0639\u064f\u0645\u064e\u0631\u064f \u0623\u064e\u062a\u064e\u062f\u0652\u0631\u0650\u064a \u0645\u064e\u0646\u0652 \u0627\u0644\u0633\u064e\u0651\u0627\u0626\u0650\u0644\u064f\u061f. \u202b\u202c\u0642\u064f\u0644\u0652\u062a\u064f: \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064f\u0647\u064f \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f. \u0642\u064e\u0627\u0644\u064e: \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u062c\u0650\u0628\u0652\u0631\u0650\u064a\u0644\u064f \u0623\u064e\u062a\u064e\u0627\u0643\u064f\u0645\u0652 \u064a\u064f\u0639\u064e\u0644\u0650\u0651\u0645\u064f\u0643\u064f\u0645\u0652 \u062f\u0650\u064a\u0646\u064e\u0643\u064f\u0645\u0652 . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0631\u064e\u0651\u062d\u0652\u0645\u064e\u0646\u0650 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0628\u0652\u0646\u0650 \u0639\u064f\u0645\u064e\u0631\u064e \u0628\u0652\u0646\u0650 \u0627\u0644\u0652\u062e\u064e\u0637\u064e\u0651\u0627\u0628\u0650 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e: \u0633\u064e\u0645\u0650\u0639\u0652\u062a \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0628\u064f\u0646\u0650\u064a\u064e \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u064f \u0639\u064e\u0644\u064e\u0649 \u062e\u064e\u0645\u0652\u0633\u064d: \u0634\u064e\u0647\u064e\u0627\u062f\u064e\u0629\u0650 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0644\u064e\u0647\u064e \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0625\u0650\u0642\u064e\u0627\u0645\u0650 \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u0650\u060c \u0648\u064e\u0625\u0650\u064a\u062a\u064e\u0627\u0621\u0650 \u0627\u0644\u0632\u064e\u0651\u0643\u064e\u0627\u0629\u0650\u060c \u0648\u064e\u062d\u064e\u062c\u0650\u0651 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u0650\u060c \u0648\u064e\u0635\u064e\u0648\u0652\u0645\u0650 \u0631\u064e\u0645\u064e\u0636\u064e\u0627\u0646\u064e . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0631\u064e\u0651\u062d\u0652\u0645\u064e\u0646\u0650 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0628\u0652\u0646\u0650 \u0645\u064e\u0633\u0652\u0639\u064f\u0648\u062f\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u062f\u064e\u0651\u062b\u064e\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 -\u0648\u064e\u0647\u064f\u0648\u064e \u0627\u0644\u0635\u064e\u0651\u0627\u062f\u0650\u0642\u064f \u0627\u0644\u0652\u0645\u064e\u0635\u0652\u062f\u064f\u0648\u0642\u064f-: \u0625\u0646\u064e\u0651 \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u0652 \u064a\u064f\u062c\u0652\u0645\u064e\u0639\u064f \u062e\u064e\u0644\u0652\u0642\u064f\u0647\u064f \u0641\u0650\u064a \u0628\u064e\u0637\u0652\u0646\u0650 \u0623\u064f\u0645\u0650\u0651\u0647\u0650 \u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650\u064a\u0646\u064e \u064a\u064e\u0648\u0652\u0645\u064b\u0627 \u0646\u064f\u0637\u0652\u0641\u064e\u0629\u064b\u060c \u062b\u064f\u0645\u064e\u0651 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0639\u064e\u0644\u064e\u0642\u064e\u0629\u064b \u0645\u0650\u062b\u0652\u0644\u064e \u0630\u064e\u0644\u0650\u0643\u064e\u060c \u062b\u064f\u0645\u064e\u0651 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0645\u064f\u0636\u0652\u063a\u064e\u0629\u064b \u0645\u0650\u062b\u0652\u0644\u064e \u0630\u064e\u0644\u0650\u0643\u064e\u060c \u062b\u064f\u0645\u064e\u0651 \u064a\u064f\u0631\u0652\u0633\u064e\u0644\u064f \u0625\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0645\u064e\u0644\u064e\u0643\u064f \u0641\u064e\u064a\u064e\u0646\u0652\u0641\u064f\u062e\u064f \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0631\u064f\u0651\u0648\u062d\u064e\u060c \u0648\u064e\u064a\u064f\u0624\u0652\u0645\u064e\u0631\u064f \u0628\u0650\u0623\u064e\u0631\u0652\u0628\u064e\u0639\u0650 \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u064d: \u0628\u0650\u0643\u064e\u062a\u0652\u0628\u0650 \u0631\u0650\u0632\u0652\u0642\u0650\u0647\u0650\u060c \u0648\u064e\u0623\u064e\u062c\u064e\u0644\u0650\u0647\u0650\u060c \u0648\u064e\u0639\u064e\u0645\u064e\u0644\u0650\u0647\u0650\u060c \u0648\u064e\u0634\u064e\u0642\u0650\u064a\u064d\u0651 \u0623\u064e\u0645\u0652 \u0633\u064e\u0639\u0650\u064a\u062f\u064d\u061b \u0641\u064e\u0648\u064e\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u0644\u064e\u0627 \u0625\u0644\u064e\u0647\u064e \u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u0625\u0646\u064e\u0651 \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0628\u0650\u0639\u064e\u0645\u064e\u0644\u0650 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u0650 \u062d\u064e\u062a\u064e\u0651\u0649 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064e\u0627 \u0625\u0644\u064e\u0651\u0627 \u0630\u0650\u0631\u064e\u0627\u0639\u064c \u0641\u064e\u064a\u064e\u0633\u0652\u0628\u0650\u0642\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0641\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0628\u0650\u0639\u064e\u0645\u064e\u0644\u0650 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650 \u0641\u064e\u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0647\u064e\u0627. \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u0623\u064e\u062d\u064e\u062f\u064e\u0643\u064f\u0645\u0652 \u0644\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0628\u0650\u0639\u064e\u0645\u064e\u0644\u0650 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650 \u062d\u064e\u062a\u064e\u0651\u0649 \u0645\u064e\u0627 \u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064e\u0627 \u0625\u0644\u064e\u0651\u0627 \u0630\u0650\u0631\u064e\u0627\u0639\u064c \u0641\u064e\u064a\u064e\u0633\u0652\u0628\u0650\u0642\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0643\u0650\u062a\u064e\u0627\u0628\u064f \u0641\u064e\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f \u0628\u0650\u0639\u064e\u0645\u064e\u0644\u0650 \u0623\u064e\u0647\u0652\u0644\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u0650 \u0641\u064e\u064a\u064e\u062f\u0652\u062e\u064f\u0644\u064f\u0647\u064e\u0627 . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064f\u0645\u0650\u0651 \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0623\u064f\u0645\u0650\u0651 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0639\u064e\u0627\u0626\u0650\u0634\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064e\u0627\u060c \u0642\u064e\u0627\u0644\u064e\u062a\u0652: \u0642\u064e\u0627\u0644\u064e: \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0645\u064e\u0646\u0652 \u0623\u064e\u062d\u0652\u062f\u064e\u062b\u064e \u0641\u0650\u064a \u0623\u064e\u0645\u0652\u0631\u0650\u0646\u064e\u0627 \u0647\u064e\u0630\u064e\u0627 \u0645\u064e\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0645\u0650\u0646\u0652\u0647\u064f \u0641\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u062f\u064c\u0651 [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c[\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c] \u0648\u064e\u0641\u0650\u064a \u0631\u0650\u0648\u064e\u0627\u064a\u064e\u0629\u064d \u0644\u0650\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064d: \u0645\u064e\u0646\u0652 \u0639\u064e\u0645\u0650\u0644\u064e \u0639\u064e\u0645\u064e\u0644\u064b\u0627 \u0644\u064e\u064a\u0652\u0633\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0623\u064e\u0645\u0652\u0631\u064f\u0646\u064e\u0627 \u0641\u064e\u0647\u064f\u0648\u064e \u0631\u064e\u062f\u064c\u0651", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u0646\u064f\u0651\u0639\u0652\u0645\u064e\u0627\u0646\u0650 \u0628\u0652\u0646\u0650 \u0628\u064e\u0634\u0650\u064a\u0631\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627\u060c \u0642\u064e\u0627\u0644\u064e: \u0633\u064e\u0645\u0650\u0639\u0652\u062a \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0625\u0646\u064e\u0651 \u0627\u0644\u0652\u062d\u064e\u0644\u064e\u0627\u0644\u064e \u0628\u064e\u064a\u0650\u0651\u0646\u064c\u060c \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e \u0628\u064e\u064a\u0650\u0651\u0646\u064c\u060c \u0648\u064e\u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u064e\u0627 \u0623\u064f\u0645\u064f\u0648\u0631\u064c \u0645\u064f\u0634\u0652\u062a\u064e\u0628\u0650\u0647\u064e\u0627\u062a\u064c \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0644\u064e\u0645\u064f\u0647\u064f\u0646\u064e\u0651 \u0643\u064e\u062b\u0650\u064a\u0631\u064c \u0645\u0650\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650\u060c \u0641\u064e\u0645\u064e\u0646\u0652 \u0627\u062a\u064e\u0651\u0642\u064e\u0649 \u0627\u0644\u0634\u064f\u0651\u0628\u064f\u0647\u064e\u0627\u062a\u0650 \u0641\u064e\u0642\u0652\u062f \u0627\u0633\u0652\u062a\u064e\u0628\u0652\u0631\u064e\u0623\u064e \u0644\u0650\u062f\u0650\u064a\u0646\u0650\u0647\u0650 \u0648\u064e\u0639\u0650\u0631\u0652\u0636\u0650\u0647\u0650\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0648\u064e\u0642\u064e\u0639\u064e \u0641\u0650\u064a \u0627\u0644\u0634\u064f\u0651\u0628\u064f\u0647\u064e\u0627\u062a\u0650 \u0648\u064e\u0642\u064e\u0639\u064e \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u060c \u0643\u064e\u0627\u0644\u0631\u064e\u0651\u0627\u0639\u0650\u064a \u064a\u064e\u0631\u0652\u0639\u064e\u0649 \u062d\u064e\u0648\u0652\u0644\u064e \u0627\u0644\u0652\u062d\u0650\u0645\u064e\u0649 \u064a\u064f\u0648\u0634\u0650\u0643\u064f \u0623\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u062a\u064e\u0639\u064e \u0641\u0650\u064a\u0647\u0650\u060c \u0623\u064e\u0644\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u0644\u0650\u0643\u064f\u0644\u0650\u0651 \u0645\u064e\u0644\u0650\u0643\u064d \u062d\u0650\u0645\u064b\u0649\u060c \u0623\u064e\u0644\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u062d\u0650\u0645\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0645\u064e\u062d\u064e\u0627\u0631\u0650\u0645\u064f\u0647\u064f\u060c \u0623\u064e\u0644\u064e\u0627 \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u0641\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0633\u064e\u062f\u0650 \u0645\u064f\u0636\u0652\u063a\u064e\u0629\u064b \u0625\u0630\u064e\u0627 \u0635\u064e\u0644\u064e\u062d\u064e\u062a\u0652 \u0635\u064e\u0644\u064e\u062d\u064e \u0627\u0644\u0652\u062c\u064e\u0633\u064e\u062f\u064f \u0643\u064f\u0644\u064f\u0651\u0647\u064f\u060c \u0648\u064e\u0625\u0630\u064e\u0627 \u0641\u064e\u0633\u064e\u062f\u064e\u062a\u0652 \u0641\u064e\u0633\u064e\u062f\u064e \u0627\u0644\u0652\u062c\u064e\u0633\u064e\u062f\u064f \u0643\u064f\u0644\u064f\u0651\u0647\u064f\u060c \u0623\u064e\u0644\u064e\u0627 \u0648\u064e\u0647\u0650\u064a\u064e \u0627\u0644\u0652\u0642\u064e\u0644\u0652\u0628\u064f .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651]\u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0631\u064f\u0642\u064e\u064a\u064e\u0651\u0629\u064e \u062a\u064e\u0645\u0650\u064a\u0645\u0650 \u0628\u0652\u0646\u0650 \u0623\u064e\u0648\u0652\u0633\u064d \u0627\u0644\u062f\u064e\u0651\u0627\u0631\u0650\u064a\u0650\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u0646\u064e\u0651 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u064e\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \"\u0627\u0644\u062f\u0650\u0651\u064a\u0646\u064f \u0627\u0644\u0646\u064e\u0651\u0635\u0650\u064a\u062d\u064e\u0629\u064f.\" \u0642\u064f\u0644\u0652\u0646\u064e\u0627: \u0644\u0650\u0645\u064e\u0646\u0652\u061f \u0642\u064e\u0627\u0644\u064e: \"\u0644\u0650\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0644\u0650\u0643\u0650\u062a\u064e\u0627\u0628\u0650\u0647\u0650\u060c \u0648\u064e\u0644\u0650\u0631\u064e\u0633\u064f\u0648\u0644\u0650\u0647\u0650\u060c \u0648\u064e\u0644\u0650\u0623\u064e\u0626\u0650\u0645\u064e\u0651\u0629\u0650 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0648\u064e\u0639\u064e\u0627\u0645\u064e\u0651\u062a\u0650\u0647\u0650\u0645\u0652.\" [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0627\u0628\u0652\u0646\u0650 \u0639\u064f\u0645\u064e\u0631\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627\u060c \u0623\u064e\u0646\u064e\u0651 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u064e\u0646\u0652 \u0623\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064e \u062d\u064e\u062a\u064e\u0651\u0649 \u064a\u064e\u0634\u0652\u0647\u064e\u062f\u064f\u0648\u0627 \u0623\u064e\u0646\u0652 \u0644\u064e\u0627 \u0625\u0644\u064e\u0647\u064e \u0625\u0644\u064e\u0651\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0648\u064e\u0623\u064e\u0646\u064e\u0651 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064b\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u064a\u064f\u0642\u0650\u064a\u0645\u064f\u0648\u0627 \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064e\u060c \u0648\u064e\u064a\u064f\u0624\u0652\u062a\u064f\u0648\u0627 \u0627\u0644\u0632\u064e\u0651\u0643\u064e\u0627\u0629\u064e\u061b \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0641\u064e\u0639\u064e\u0644\u064f\u0648\u0627 \u0630\u064e\u0644\u0650\u0643\u064e \u0639\u064e\u0635\u064e\u0645\u064f\u0648\u0627 \u0645\u0650\u0646\u0650\u0651\u064a \u062f\u0650\u0645\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652 \u0648\u064e\u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e\u0647\u064f\u0645\u0652 \u0625\u0644\u064e\u0651\u0627 \u0628\u0650\u062d\u064e\u0642\u0650\u0651 \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650\u060c \u0648\u064e\u062d\u0650\u0633\u064e\u0627\u0628\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c[\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0631\u064e\u0651\u062d\u0652\u0645\u064e\u0646\u0650 \u0628\u0652\u0646\u0650 \u0635\u064e\u062e\u0652\u0631\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0633\u064e\u0645\u0650\u0639\u0652\u062a \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0645\u064e\u0627 \u0646\u064e\u0647\u064e\u064a\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652\u0647\u064f \u0641\u064e\u0627\u062c\u0652\u062a\u064e\u0646\u0650\u0628\u064f\u0648\u0647\u064f\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u0652\u062a\u064f\u0643\u064f\u0645\u0652 \u0628\u0650\u0647\u0650 \u0641\u064e\u0623\u0652\u062a\u064f\u0648\u0627 \u0645\u0650\u0646\u0652\u0647\u064f \u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0639\u0652\u062a\u064f\u0645\u0652\u060c \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0645\u064e\u0627 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u064e \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0645\u0650\u0646\u0652 \u0642\u064e\u0628\u0652\u0644\u0650\u0643\u064f\u0645\u0652 \u0643\u064e\u062b\u0652\u0631\u064e\u0629\u064f \u0645\u064e\u0633\u064e\u0627\u0626\u0650\u0644\u0650\u0647\u0650\u0645\u0652 \u0648\u064e\u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0646\u0652\u0628\u0650\u064a\u064e\u0627\u0626\u0650\u0647\u0650\u0645\u0652 .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c[\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \"\u0625\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0637\u064e\u064a\u0650\u0651\u0628\u064c \u0644\u064e\u0627 \u064a\u064e\u0642\u0652\u0628\u064e\u0644\u064f \u0625\u0644\u064e\u0651\u0627 \u0637\u064e\u064a\u0650\u0651\u0628\u064b\u0627\u060c \u0648\u064e\u0625\u0650\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0623\u064e\u0645\u064e\u0631\u064e \u0627\u0644\u0652\u0645\u064f\u0624\u0652\u0645\u0650\u0646\u0650\u064a\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u0645\u064e\u0631\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0631\u0652\u0633\u064e\u0644\u0650\u064a\u0646\u064e \u0641\u064e\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649: \"\u064a\u064e\u0627 \u0623\u064e\u064a\u064f\u0651\u0647\u064e\u0627 \u0627\u0644\u0631\u064f\u0651\u0633\u064f\u0644\u064f \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0627\u0644\u0637\u064e\u0651\u064a\u0650\u0651\u0628\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0627 \u0635\u064e\u0627\u0644\u0650\u062d\u064b\u0627\"\u060c \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649: \"\u064a\u064e\u0627 \u0623\u064e\u064a\u064f\u0651\u0647\u064e\u0627 \u0627\u0644\u064e\u0651\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0643\u064f\u0644\u064f\u0648\u0627 \u0645\u0650\u0646\u0652 \u0637\u064e\u064a\u0650\u0651\u0628\u064e\u0627\u062a\u0650 \u0645\u064e\u0627 \u0631\u064e\u0632\u064e\u0642\u0652\u0646\u064e\u0627\u0643\u064f\u0645\u0652\" \u062b\u064f\u0645\u064e\u0651 \u0630\u064e\u0643\u064e\u0631\u064e \u0627\u0644\u0631\u064e\u0651\u062c\u064f\u0644\u064e \u064a\u064f\u0637\u0650\u064a\u0644\u064f \u0627\u0644\u0633\u064e\u0651\u0641\u064e\u0631\u064e \u0623\u064e\u0634\u0652\u0639\u064e\u062b\u064e \u0623\u064e\u063a\u0652\u0628\u064e\u0631\u064e \u064a\u064e\u0645\u064f\u062f\u064f\u0651 \u064a\u064e\u062f\u064e\u064a\u0652\u0647\u0650 \u0625\u0644\u064e\u0649 \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650: \u064a\u064e\u0627 \u0631\u064e\u0628\u0650\u0651! \u064a\u064e\u0627 \u0631\u064e\u0628\u0650\u0651! \u0648\u064e\u0645\u064e\u0637\u0652\u0639\u064e\u0645\u064f\u0647\u064f \u062d\u064e\u0631\u064e\u0627\u0645\u064c\u060c \u0648\u064e\u0645\u064e\u0634\u0652\u0631\u064e\u0628\u064f\u0647\u064f \u062d\u064e\u0631\u064e\u0627\u0645\u064c\u060c \u0648\u064e\u0645\u064e\u0644\u0652\u0628\u064e\u0633\u064f\u0647\u064f \u062d\u064e\u0631\u064e\u0627\u0645\u064c\u060c \u0648\u064e\u063a\u064f\u0630\u0650\u0651\u064a\u064e \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650\u060c \u0641\u064e\u0623\u064e\u0646\u064e\u0651\u0649 \u064a\u064f\u0633\u0652\u062a\u064e\u062c\u064e\u0627\u0628\u064f \u0644\u064e\u0647\u064f\u061f\". [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u0650 \u0628\u0652\u0646\u0650 \u0639\u064e\u0644\u0650\u064a\u0650\u0651 \u0628\u0652\u0646\u0650 \u0623\u064e\u0628\u0650\u064a \u0637\u064e\u0627\u0644\u0650\u0628\u064d \u0633\u0650\u0628\u0652\u0637\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0648\u064e\u0631\u064e\u064a\u0652\u062d\u064e\u0627\u0646\u064e\u062a\u0650\u0647\u0650 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627\u060c \u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u0641\u0650\u0638\u0652\u062a \u0645\u0650\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u062f\u064e\u0639\u0652 \u0645\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u0628\u064f\u0643 \u0625\u0644\u064e\u0649 \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064f\u0631\u0650\u064a\u0628\u064f\u0643 . \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:2520]\u060c [\u0648\u064e\u0627\u0644\u0646\u064e\u0651\u0633\u064e\u0627\u0626\u0650\u064a\u0651] \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651: \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0645\u0650\u0646\u0652 \u062d\u064f\u0633\u0652\u0646\u0650 \u0625\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u0627\u0644\u0652\u0645\u064e\u0631\u0652\u0621\u0650 \u062a\u064e\u0631\u0652\u0643\u064f\u0647\u064f \u0645\u064e\u0627 \u0644\u064e\u0627 \u064a\u064e\u0639\u0652\u0646\u0650\u064a\u0647\u0650 . \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645: 2318] \u060c \u0627\u0628\u0646 \u0645\u0627\u062c\u0647 [\u0631\u0642\u0645:]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u062d\u064e\u0645\u0652\u0632\u064e\u0629\u064e \u0623\u064e\u0646\u064e\u0633\u0650 \u0628\u0652\u0646\u0650 \u0645\u064e\u0627\u0644\u0650\u0643\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u062e\u064e\u0627\u062f\u0650\u0645\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0639\u064e\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u064e\u0651\u0649 \u064a\u064f\u062d\u0650\u0628\u064e\u0651 \u0644\u0650\u0623\u064e\u062e\u0650\u064a\u0647\u0650 \u0645\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u064f\u0651 \u0644\u0650\u0646\u064e\u0641\u0652\u0633\u0650\u0647\u0650 . \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:13]\u060c \u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c [\u0631\u0642\u0645:45].<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0627\u0628\u0652\u0646\u0650 \u0645\u064e\u0633\u0652\u0639\u064f\u0648\u062f\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0644\u064e\u0627 \u064a\u064e\u062d\u0650\u0644\u064f\u0651 \u062f\u064e\u0645\u064f \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064d [ \u064a\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647] \u0625\u0644\u064e\u0651\u0627 \u0628\u0650\u0625\u0650\u062d\u0652\u062f\u064e\u0649 \u062b\u064e\u0644\u064e\u0627\u062b\u064d: \u0627\u0644\u062b\u064e\u0651\u064a\u0650\u0651\u0628\u064f \u0627\u0644\u0632\u064e\u0651\u0627\u0646\u0650\u064a\u060c \u0648\u064e\u0627\u0644\u0646\u064e\u0651\u0641\u0652\u0633\u064f \u0628\u0650\u0627\u0644\u0646\u064e\u0651\u0641\u0652\u0633\u0650\u060c \u0648\u064e\u0627\u0644\u062a\u064e\u0651\u0627\u0631\u0650\u0643\u064f \u0644\u0650\u062f\u0650\u064a\u0646\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u0641\u064e\u0627\u0631\u0650\u0642\u064f \u0644\u0650\u0644\u0652\u062c\u064e\u0645\u064e\u0627\u0639\u064e\u0629\u0650 .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u0646\u064e\u0651 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0641\u064e\u0644\u0652\u064a\u064e\u0642\u064f\u0644\u0652 \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0623\u064e\u0648\u0652 \u0644\u0650\u064a\u064e\u0635\u0652\u0645\u064f\u062a\u0652\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0641\u064e\u0644\u0652\u064a\u064f\u0643\u0652\u0631\u0650\u0645\u0652 \u062c\u064e\u0627\u0631\u064e\u0647\u064f\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0643\u064e\u0627\u0646\u064e \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0628\u0650\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0622\u062e\u0650\u0631\u0650 \u0641\u064e\u0644\u0652\u064a\u064f\u0643\u0652\u0631\u0650\u0645\u0652 \u0636\u064e\u064a\u0652\u0641\u064e\u0647\u064f .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u0646\u0651\u064e \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0642\u064e\u0627\u0644\u064e \u0644\u0650\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0623\u064e\u0648\u0652\u0635\u0650\u0646\u0650\u064a. \u0642\u064e\u0627\u0644\u064e: \u0644\u064e\u0627 \u062a\u064e\u063a\u0652\u0636\u064e\u0628\u0652\u060c \u0641\u064e\u0631\u064e\u062f\u064e\u0651\u062f\u064e \u0645\u0650\u0631\u064e\u0627\u0631\u064b\u0627\u060c \u0642\u064e\u0627\u0644\u064e: \u0644\u064e\u0627 \u062a\u064e\u063a\u0652\u0636\u064e\u0628\u0652\" .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u064a\u064e\u0639\u0652\u0644\u064e\u0649 \u0634\u064e\u062f\u064e\u0651\u0627\u062f\u0650 \u0628\u0652\u0646\u0650 \u0623\u064e\u0648\u0652\u0633\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0639\u064e\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \u0625\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0652\u0625\u0650\u062d\u0652\u0633\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0643\u064f\u0644\u0650\u0651 \u0634\u064e\u064a\u0652\u0621\u064d\u060c \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0642\u064e\u062a\u064e\u0644\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0627 \u0627\u0644\u0652\u0642\u0650\u062a\u0652\u0644\u064e\u0629\u064e\u060c \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0630\u064e\u0628\u064e\u062d\u0652\u062a\u064f\u0645\u0652 \u0641\u064e\u0623\u064e\u062d\u0652\u0633\u0650\u0646\u064f\u0648\u0627 \u0627\u0644\u0630\u0650\u0651\u0628\u0652\u062d\u064e\u0629\u064e\u060c \u0648\u064e\u0644\u0652\u064a\u064f\u062d\u0650\u062f\u064e\u0651 \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u0652 \u0634\u064e\u0641\u0652\u0631\u064e\u062a\u064e\u0647\u064f\u060c \u0648\u064e\u0644\u0652\u064a\u064f\u0631\u0650\u062d\u0652 \u0630\u064e\u0628\u0650\u064a\u062d\u064e\u062a\u064e\u0647\u064f . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0630\u064e\u0631\u064d\u0651 \u062c\u064f\u0646\u0652\u062f\u064e\u0628\u0650 \u0628\u0652\u0646\u0650 \u062c\u064f\u0646\u064e\u0627\u062f\u064e\u0629\u064e\u060c \u0648\u064e\u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0631\u064e\u0651\u062d\u0652\u0645\u064e\u0646\u0650 \u0645\u064f\u0639\u064e\u0627\u0630\u0650 \u0628\u0652\u0646\u0650 \u062c\u064e\u0628\u064e\u0644\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627\u060c \u0639\u064e\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \u0627\u062a\u064e\u0651\u0642\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062d\u064e\u064a\u0652\u062b\u064f\u0645\u064e\u0627 \u0643\u064f\u0646\u0652\u062a\u060c \u0648\u064e\u0623\u064e\u062a\u0652\u0628\u0650\u0639\u0652 \u0627\u0644\u0633\u064e\u0651\u064a\u0650\u0651\u0626\u064e\u0629\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064e \u062a\u064e\u0645\u0652\u062d\u064f\u0647\u064e\u0627\u060c \u0648\u064e\u062e\u064e\u0627\u0644\u0650\u0642\u0652 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064e \u0628\u0650\u062e\u064f\u0644\u064f\u0642\u064d \u062d\u064e\u0633\u064e\u0646\u064d . \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:1987] \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0648\u064e\u0641\u0650\u064a \u0628\u064e\u0639\u0652\u0636\u0650 \u0627\u0644\u0646\u064f\u0651\u0633\u064e\u062e\u0650: \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c", "\u0639\u064e\u0646\u0652 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0628\u0652\u0646\u0650 \u0639\u064e\u0628\u064e\u0651\u0627\u0633\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e: \"\u0643\u064f\u0646\u0652\u062a \u062e\u064e\u0644\u0652\u0641\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0648\u0652\u0645\u064b\u0627\u060c \u0641\u064e\u0642\u064e\u0627\u0644\u064e: \u064a\u064e\u0627 \u063a\u064f\u0644\u064e\u0627\u0645\u0650! \u0625\u0646\u0650\u0651\u064a \u0623\u064f\u0639\u064e\u0644\u0650\u0651\u0645\u064f\u0643 \u0643\u064e\u0644\u0650\u0645\u064e\u0627\u062a\u064d: \u0627\u062d\u0652\u0641\u064e\u0638\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u064a\u064e\u062d\u0652\u0641\u064e\u0638\u0652\u0643\u060c \u0627\u062d\u0652\u0641\u064e\u0638\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062a\u064e\u062c\u0650\u062f\u0652\u0647\u064f \u062a\u064f\u062c\u064e\u0627\u0647\u064e\u0643\u060c \u0625\u0630\u064e\u0627 \u0633\u064e\u0623\u064e\u0644\u0652\u062a \u0641\u064e\u0627\u0633\u0652\u0623\u064e\u0644\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064e\u060c \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0627\u0633\u0652\u062a\u064e\u0639\u064e\u0646\u0652\u062a \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0639\u0650\u0646\u0652 \u0628\u0650\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u064e\u0651 \u0627\u0644\u0652\u0623\u064f\u0645\u064e\u0651\u0629\u064e \u0644\u064e\u0648\u0652 \u0627\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0646\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0648\u0643 \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0644\u064e\u0645\u0652 \u064a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0648\u0643 \u0625\u0644\u064e\u0651\u0627 \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0652 \u0643\u064e\u062a\u064e\u0628\u064e\u0647\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u064e\u0643\u060c \u0648\u064e\u0625\u0650\u0646\u0652 \u0627\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0646\u0652 \u064a\u064e\u0636\u064f\u0631\u064f\u0651\u0648\u0643 \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0644\u064e\u0645\u0652 \u064a\u064e\u0636\u064f\u0631\u064f\u0651\u0648\u0643 \u0625\u0644\u064e\u0651\u0627 \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0642\u064e\u062f\u0652 \u0643\u064e\u062a\u064e\u0628\u064e\u0647\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u061b \u0631\u064f\u0641\u0650\u0639\u064e\u062a\u0652 \u0627\u0644\u0652\u0623\u064e\u0642\u0652\u0644\u064e\u0627\u0645\u064f\u060c \u0648\u064e\u062c\u064e\u0641\u064e\u0651\u062a\u0652 \u0627\u0644\u0635\u064f\u0651\u062d\u064f\u0641\u064f\" . \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:2516] \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c. \u0648\u064e\u0641\u0650\u064a \u0631\u0650\u0648\u064e\u0627\u064a\u064e\u0629\u0650 \u063a\u064e\u064a\u0652\u0631\u0650 \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u0650\u0651: \"\u0627\u062d\u0652\u0641\u064e\u0638\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062a\u064e\u062c\u0650\u062f\u0652\u0647\u064f \u0623\u0645\u0627\u0645\u0643\u060c \u062a\u064e\u0639\u064e\u0631\u064e\u0651\u0641\u0652 \u0625\u0644\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u0631\u064e\u0651\u062e\u064e\u0627\u0621\u0650 \u064a\u064e\u0639\u0652\u0631\u0650\u0641\u064f\u0643 \u0641\u0650\u064a \u0627\u0644\u0634\u0650\u0651\u062f\u064e\u0651\u0629\u0650\u060c \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u064e\u0651 \u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0637\u064e\u0623\u064e\u0643 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u0650\u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0643\u060c \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0635\u064e\u0627\u0628\u064e\u0643 \u0644\u064e\u0645\u0652 \u064a\u064e\u0643\u064f\u0646\u0652 \u0644\u0650\u064a\u064f\u062e\u0652\u0637\u0650\u0626\u064e\u0643\u060c \u0648\u064e\u0627\u0639\u0652\u0644\u064e\u0645\u0652 \u0623\u064e\u0646\u064e\u0651 \u0627\u0644\u0646\u064e\u0651\u0635\u0652\u0631\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0635\u064e\u0651\u0628\u0652\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u0652 \u0627\u0644\u0652\u0641\u064e\u0631\u064e\u062c\u064e \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0643\u064e\u0631\u0652\u0628\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u064e\u0651 \u0645\u064e\u0639\u064e \u0627\u0644\u0652\u0639\u064f\u0633\u0652\u0631\u0650 \u064a\u064f\u0633\u0652\u0631\u064b\u0627", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0645\u064e\u0633\u0652\u0639\u064f\u0648\u062f\u064d \u0639\u064f\u0642\u0652\u0628\u064e\u0629\u064e \u0628\u0652\u0646\u0650 \u0639\u064e\u0645\u0652\u0631\u064d\u0648 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u0650\u064a\u0650\u0651 \u0627\u0644\u0652\u0628\u064e\u062f\u0652\u0631\u0650\u064a\u0650\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0625\u0646\u064e\u0651 \u0645\u0650\u0645\u064e\u0651\u0627 \u0623\u064e\u062f\u0652\u0631\u064e\u0643\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f \u0645\u0650\u0646\u0652 \u0643\u064e\u0644\u064e\u0627\u0645\u0650 \u0627\u0644\u0646\u064f\u0651\u0628\u064f\u0648\u064e\u0651\u0629\u0650 \u0627\u0644\u0652\u0623\u064f\u0648\u0644\u064e\u0649: \u0625\u0630\u064e\u0627 \u0644\u064e\u0645\u0652 \u062a\u064e\u0633\u0652\u062a\u064e\u062d\u0650 \u0641\u064e\u0627\u0635\u0652\u0646\u064e\u0639\u0652 \u0645\u064e\u0627 \u0634\u0650\u0626\u0652\u062a .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0645\u0652\u0631\u064d\u0648 \u0648\u064e\u0642\u0650\u064a\u0644\u064e: \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0645\u0652\u0631\u064e\u0629\u064e \u0633\u064f\u0641\u0652\u064a\u064e\u0627\u0646\u064e \u0628\u0652\u0646\u0650 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064f\u0644\u0652\u062a: \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650! \u0642\u064f\u0644\u0652 \u0644\u0650\u064a \u0641\u0650\u064a \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u0650 \u0642\u064e\u0648\u0652\u0644\u064b\u0627 \u0644\u064e\u0627 \u0623\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u062d\u064e\u062f\u064b\u0627 \u063a\u064e\u064a\u0652\u0631\u064e\u0643\u061b \u0642\u064e\u0627\u0644\u064e: \u0642\u064f\u0644\u0652: \u0622\u0645\u064e\u0646\u0652\u062a \u0628\u0650\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u0650 \u062b\u064f\u0645\u064e\u0651 \u0627\u0633\u0652\u062a\u064e\u0642\u0650\u0645\u0652 . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u062c\u064e\u0627\u0628\u0650\u0631\u0650 \u0628\u0652\u0646\u0650 \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0627\u0644\u0652\u0623\u064e\u0646\u0652\u0635\u064e\u0627\u0631\u0650\u064a\u0650\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627: \u0623\u064e\u0646\u064e\u0651 \u0631\u064e\u062c\u064f\u0644\u064b\u0627 \u0633\u064e\u0623\u064e\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0641\u064e\u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a \u0625\u0630\u064e\u0627 \u0635\u064e\u0644\u064e\u0651\u064a\u0652\u062a \u0627\u0644\u0652\u0645\u064e\u0643\u0652\u062a\u064f\u0648\u0628\u064e\u0627\u062a\u0650\u060c \u0648\u064e\u0635\u064f\u0645\u0652\u062a \u0631\u064e\u0645\u064e\u0636\u064e\u0627\u0646\u064e\u060c \u0648\u064e\u0623\u064e\u062d\u0652\u0644\u064e\u0644\u0652\u062a \u0627\u0644\u0652\u062d\u064e\u0644\u064e\u0627\u0644\u064e\u060c \u0648\u064e\u062d\u064e\u0631\u064e\u0651\u0645\u0652\u062a \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u064e\u060c \u0648\u064e\u0644\u064e\u0645\u0652 \u0623\u064e\u0632\u0650\u062f\u0652 \u0639\u064e\u0644\u064e\u0649 \u0630\u064e\u0644\u0650\u0643\u064e \u0634\u064e\u064a\u0652\u0626\u064b\u0627\u061b \u0623\u064e\u0623\u064e\u062f\u0652\u062e\u064f\u0644\u064f \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064e\u061f \u0642\u064e\u0627\u0644\u064e: \u0646\u064e\u0639\u064e\u0645\u0652 . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0645\u064e\u0627\u0644\u0650\u0643\u064d \u0627\u0644\u0652\u062d\u064e\u0627\u0631\u0650\u062b\u0650 \u0628\u0652\u0646\u0650 \u0639\u064e\u0627\u0635\u0650\u0645\u064d \u0627\u0644\u0652\u0623\u064e\u0634\u0652\u0639\u064e\u0631\u0650\u064a\u0650\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0627\u0644\u0637\u064e\u0651\u0647\u064f\u0648\u0631\u064f \u0634\u064e\u0637\u0652\u0631\u064f \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u062a\u064e\u0645\u0652\u0644\u064e\u0623\u064f \u0627\u0644\u0652\u0645\u0650\u064a\u0632\u064e\u0627\u0646\u064e\u060c \u0648\u064e\u0633\u064f\u0628\u0652\u062d\u064e\u0627\u0646\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u062d\u064e\u0645\u0652\u062f\u064f \u0644\u0650\u0644\u064e\u0651\u0647\u0650 \u062a\u064e\u0645\u0652\u0644\u064e\u0622\u0646\u0650 -\u0623\u064e\u0648\u0652: \u062a\u064e\u0645\u0652\u0644\u064e\u0623\u064f- \u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650\u060c \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064f \u0646\u064f\u0648\u0631\u064c\u060c \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u062f\u064e\u0642\u064e\u0629\u064f \u0628\u064f\u0631\u0652\u0647\u064e\u0627\u0646\u064c\u060c \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u0628\u0652\u0631\u064f \u0636\u0650\u064a\u064e\u0627\u0621\u064c\u060c \u0648\u064e\u0627\u0644\u0652\u0642\u064f\u0631\u0652\u0622\u0646\u064f \u062d\u064f\u062c\u064e\u0651\u0629\u064c \u0644\u064e\u0643 \u0623\u064e\u0648\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u060c \u0643\u064f\u0644\u064f\u0651 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u064a\u064e\u063a\u0652\u062f\u064f\u0648\u060c \u0641\u064e\u0628\u064e\u0627\u0626\u0650\u0639\u064c \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f \u0641\u064e\u0645\u064f\u0639\u0652\u062a\u0650\u0642\u064f\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u0645\u064f\u0648\u0628\u0650\u0642\u064f\u0647\u064e\u0627 . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0630\u064e\u0631\u064d\u0651 \u0627\u0644\u0652\u063a\u0650\u0641\u064e\u0627\u0631\u0650\u064a\u0650\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0639\u064e\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0641\u0650\u064a\u0645\u064e\u0627 \u064a\u064e\u0631\u0652\u0648\u0650\u064a\u0647\u0650 \u0639\u064e\u0646\u0652 \u0631\u064e\u0628\u0650\u0651\u0647\u0650 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u060c \u0623\u064e\u0646\u064e\u0651\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a: \u0625\u0646\u0650\u0651\u064a \u062d\u064e\u0631\u064e\u0651\u0645\u0652\u062a \u0627\u0644\u0638\u064f\u0651\u0644\u0652\u0645\u064e \u0639\u064e\u0644\u064e\u0649 \u0646\u064e\u0641\u0652\u0633\u0650\u064a\u060c \u0648\u064e\u062c\u064e\u0639\u064e\u0644\u0652\u062a\u0647 \u0628\u064e\u064a\u0652\u0646\u064e\u0643\u064f\u0645\u0652 \u0645\u064f\u062d\u064e\u0631\u064e\u0651\u0645\u064b\u0627\u061b \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0638\u064e\u0627\u0644\u064e\u0645\u064f\u0648\u0627. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0643\u064f\u0644\u064f\u0651\u0643\u064f\u0645\u0652 \u0636\u064e\u0627\u0644\u064c\u0651 \u0625\u0644\u064e\u0651\u0627 \u0645\u064e\u0646\u0652 \u0647\u064e\u062f\u064e\u064a\u0652\u062a\u0647\u060c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0647\u0652\u062f\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0647\u0652\u062f\u0650\u0643\u064f\u0645\u0652. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0643\u064f\u0644\u064f\u0651\u0643\u064f\u0645\u0652 \u062c\u064e\u0627\u0626\u0650\u0639\u064c \u0625\u0644\u064e\u0651\u0627 \u0645\u064e\u0646\u0652 \u0623\u064e\u0637\u0652\u0639\u064e\u0645\u0652\u062a\u0647\u060c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0637\u0652\u0639\u0650\u0645\u064f\u0648\u0646\u0650\u064a \u0623\u064f\u0637\u0652\u0639\u0650\u0645\u0652\u0643\u064f\u0645\u0652. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0643\u064f\u0644\u064f\u0651\u0643\u064f\u0645\u0652 \u0639\u064e\u0627\u0631\u064d \u0625\u0644\u064e\u0651\u0627 \u0645\u064e\u0646\u0652 \u0643\u064e\u0633\u064e\u0648\u0652\u062a\u0647\u060c \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u0643\u0652\u0633\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u0643\u0652\u0633\u064f\u0643\u064f\u0645\u0652. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0625\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u062a\u064f\u062e\u0652\u0637\u0650\u0626\u064f\u0648\u0646\u064e \u0628\u0650\u0627\u0644\u0644\u064e\u0651\u064a\u0652\u0644\u0650 \u0648\u064e\u0627\u0644\u0646\u064e\u0651\u0647\u064e\u0627\u0631\u0650\u060c \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0627\u0644\u0630\u064f\u0651\u0646\u064f\u0648\u0628\u064e \u062c\u064e\u0645\u0650\u064a\u0639\u064b\u0627\u061b \u0641\u064e\u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f\u0648\u0646\u0650\u064a \u0623\u064e\u063a\u0652\u0641\u0650\u0631\u0652 \u0644\u064e\u0643\u064f\u0645\u0652. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0625\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0644\u064e\u0646\u0652 \u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0636\u064f\u0631\u0650\u0651\u064a \u0641\u064e\u062a\u064e\u0636\u064f\u0631\u064f\u0651\u0648\u0646\u0650\u064a\u060c \u0648\u064e\u0644\u064e\u0646\u0652 \u062a\u064e\u0628\u0652\u0644\u064f\u063a\u064f\u0648\u0627 \u0646\u064e\u0641\u0652\u0639\u0650\u064a \u0641\u064e\u062a\u064e\u0646\u0652\u0641\u064e\u0639\u064f\u0648\u0646\u0650\u064a. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u064e\u0651 \u0623\u064e\u0648\u064e\u0651\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0622\u062e\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u0650\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u062a\u0652\u0642\u064e\u0649 \u0642\u064e\u0644\u0652\u0628\u0650 \u0631\u064e\u062c\u064f\u0644\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652\u060c \u0645\u064e\u0627 \u0632\u064e\u0627\u062f\u064e \u0630\u064e\u0644\u0650\u0643\u064e \u0641\u0650\u064a \u0645\u064f\u0644\u0652\u0643\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u064e\u0651 \u0623\u064e\u0648\u064e\u0651\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0622\u062e\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u0650\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0641\u0652\u062c\u064e\u0631\u0650 \u0642\u064e\u0644\u0652\u0628\u0650 \u0631\u064e\u062c\u064f\u0644\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652\u060c \u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0635\u064e \u0630\u064e\u0644\u0650\u0643\u064e \u0645\u0650\u0646\u0652 \u0645\u064f\u0644\u0652\u0643\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0644\u064e\u0648\u0652 \u0623\u064e\u0646\u064e\u0651 \u0623\u064e\u0648\u064e\u0651\u0644\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0622\u062e\u0650\u0631\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u0625\u0650\u0646\u0652\u0633\u064e\u0643\u064f\u0645\u0652 \u0648\u064e\u062c\u0650\u0646\u064e\u0651\u0643\u064f\u0645\u0652 \u0642\u064e\u0627\u0645\u064f\u0648\u0627 \u0641\u0650\u064a \u0635\u064e\u0639\u0650\u064a\u062f\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064d\u060c \u0641\u064e\u0633\u064e\u0623\u064e\u0644\u064f\u0648\u0646\u0650\u064a\u060c \u0641\u064e\u0623\u064e\u0639\u0652\u0637\u064e\u064a\u0652\u062a \u0643\u064f\u0644\u064e\u0651 \u0648\u064e\u0627\u062d\u0650\u062f\u064d \u0645\u064e\u0633\u0652\u0623\u064e\u0644\u064e\u062a\u0647\u060c \u0645\u064e\u0627 \u0646\u064e\u0642\u064e\u0635\u064e \u0630\u064e\u0644\u0650\u0643\u064e \u0645\u0650\u0645\u064e\u0651\u0627 \u0639\u0650\u0646\u0652\u062f\u0650\u064a \u0625\u0644\u064e\u0651\u0627 \u0643\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0652\u0642\u064f\u0635\u064f \u0627\u0644\u0652\u0645\u0650\u062e\u0652\u064a\u064e\u0637\u064f \u0625\u0630\u064e\u0627 \u0623\u064f\u062f\u0652\u062e\u0650\u0644\u064e \u0627\u0644\u0652\u0628\u064e\u062d\u0652\u0631\u064e. \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650\u064a! \u0625\u0646\u064e\u0651\u0645\u064e\u0627 \u0647\u0650\u064a\u064e \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0643\u064f\u0645\u0652 \u0623\u064f\u062d\u0652\u0635\u0650\u064a\u0647\u064e\u0627 \u0644\u064e\u0643\u064f\u0645\u0652\u060c \u062b\u064f\u0645\u064e\u0651 \u0623\u064f\u0648\u064e\u0641\u0650\u0651\u064a\u0643\u064f\u0645\u0652 \u0625\u064a\u064e\u0651\u0627\u0647\u064e\u0627\u061b \u0641\u064e\u0645\u064e\u0646\u0652 \u0648\u064e\u062c\u064e\u062f\u064e \u062e\u064e\u064a\u0652\u0631\u064b\u0627 \u0641\u064e\u0644\u0652\u064a\u064e\u062d\u0652\u0645\u064e\u062f\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064e\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0648\u064e\u062c\u064e\u062f\u064e \u063a\u064e\u064a\u0652\u0631\u064e \u0630\u064e\u0644\u0650\u0643\u064e \u0641\u064e\u0644\u064e\u0627 \u064a\u064e\u0644\u064f\u0648\u0645\u064e\u0646 \u0625\u0644\u064e\u0651\u0627 \u0646\u064e\u0641\u0652\u0633\u064e\u0647\u064f . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0630\u064e\u0631\u064d\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u064a\u0652\u0636\u064b\u0627\u060c \u0623\u064e\u0646\u064e\u0651 \u0646\u064e\u0627\u0633\u064b\u0627 \u0645\u0650\u0646\u0652 \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u0650 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064f\u0648\u0627 \u0644\u0650\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0630\u064e\u0647\u064e\u0628\u064e \u0623\u064e\u0647\u0652\u0644\u064f \u0627\u0644\u062f\u064f\u0651\u062b\u064f\u0648\u0631\u0650 \u0628\u0650\u0627\u0644\u0652\u0623\u064f\u062c\u064f\u0648\u0631\u0650\u061b \u064a\u064f\u0635\u064e\u0644\u064f\u0651\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0646\u064f\u0635\u064e\u0644\u0650\u0651\u064a\u060c \u0648\u064e\u064a\u064e\u0635\u064f\u0648\u0645\u064f\u0648\u0646\u064e \u0643\u064e\u0645\u064e\u0627 \u0646\u064e\u0635\u064f\u0648\u0645\u064f\u060c \u0648\u064e\u064a\u064e\u062a\u064e\u0635\u064e\u062f\u064e\u0651\u0642\u064f\u0648\u0646\u064e \u0628\u0650\u0641\u064f\u0636\u064f\u0648\u0644\u0650 \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u0650\u0647\u0650\u0645\u0652. \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0648\u064e\u0644\u064e\u064a\u0652\u0633\u064e \u0642\u064e\u062f\u0652 \u062c\u064e\u0639\u064e\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u064e\u0643\u064f\u0645\u0652 \u0645\u064e\u0627 \u062a\u064e\u0635\u064e\u0651\u062f\u064e\u0651\u0642\u064f\u0648\u0646\u064e\u061f \u0625\u0646\u064e\u0651 \u0628\u0650\u0643\u064f\u0644\u0650\u0651 \u062a\u064e\u0633\u0652\u0628\u0650\u064a\u062d\u064e\u0629\u064d \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064b\u060c \u0648\u064e\u0643\u064f\u0644\u0650\u0651 \u062a\u064e\u0643\u0652\u0628\u0650\u064a\u0631\u064e\u0629\u064d \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064b\u060c \u0648\u064e\u0643\u064f\u0644\u0650\u0651 \u062a\u064e\u062d\u0652\u0645\u0650\u064a\u062f\u064e\u0629\u064d \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064b\u060c \u0648\u064e\u0643\u064f\u0644\u0650\u0651 \u062a\u064e\u0647\u0652\u0644\u0650\u064a\u0644\u064e\u0629\u064d \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064b\u060c \u0648\u064e\u0623\u064e\u0645\u0652\u0631\u064c \u0628\u0650\u0645\u064e\u0639\u0652\u0631\u064f\u0648\u0641\u064d \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0648\u064e\u0646\u064e\u0647\u0652\u064a\u064c \u0639\u064e\u0646\u0652 \u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064d \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0648\u064e\u0641\u0650\u064a \u0628\u064f\u0636\u0652\u0639\u0650 \u0623\u064e\u062d\u064e\u062f\u0650\u0643\u064f\u0645\u0652 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c. \u0642\u064e\u0627\u0644\u064f\u0648\u0627: \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0623\u064e\u064a\u064e\u0623\u0652\u062a\u0650\u064a \u0623\u064e\u062d\u064e\u062f\u064f\u0646\u064e\u0627 \u0634\u064e\u0647\u0652\u0648\u064e\u062a\u064e\u0647\u064f \u0648\u064e\u064a\u064e\u0643\u064f\u0648\u0646\u064f \u0644\u064e\u0647\u064f \u0641\u0650\u064a\u0647\u064e\u0627 \u0623\u064e\u062c\u0652\u0631\u064c\u061f \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0631\u064e\u0623\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0644\u064e\u0648\u0652 \u0648\u064e\u0636\u064e\u0639\u064e\u0647\u064e\u0627 \u0641\u0650\u064a \u062d\u064e\u0631\u064e\u0627\u0645\u064d \u0623\u064e\u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0648\u0650\u0632\u0652\u0631\u064c\u061f \u0641\u064e\u0643\u064e\u0630\u064e\u0644\u0650\u0643\u064e \u0625\u0630\u064e\u0627 \u0648\u064e\u0636\u064e\u0639\u064e\u0647\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0652\u062d\u064e\u0644\u064e\u0627\u0644\u0650\u060c \u0643\u064e\u0627\u0646\u064e \u0644\u064e\u0647\u064f \u0623\u064e\u062c\u0652\u0631\u064c . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0643\u064f\u0644\u064f\u0651 \u0633\u064f\u0644\u064e\u0627\u0645\u064e\u0649 \u0645\u0650\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0643\u064f\u0644\u064e\u0651 \u064a\u064e\u0648\u0652\u0645\u064d \u062a\u064e\u0637\u0652\u0644\u064f\u0639\u064f \u0641\u0650\u064a\u0647\u0650 \u0627\u0644\u0634\u064e\u0651\u0645\u0652\u0633\u064f \u062a\u064e\u0639\u0652\u062f\u0650\u0644\u064f \u0628\u064e\u064a\u0652\u0646\u064e \u0627\u062b\u0652\u0646\u064e\u064a\u0652\u0646\u0650 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0648\u064e\u062a\u064f\u0639\u0650\u064a\u0646\u064f \u0627\u0644\u0631\u064e\u0651\u062c\u064f\u0644\u064e \u0641\u0650\u064a \u062f\u064e\u0627\u0628\u064e\u0651\u062a\u0650\u0647\u0650 \u0641\u064e\u062a\u064e\u062d\u0652\u0645\u0650\u0644\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0623\u064e\u0648\u0652 \u062a\u064e\u0631\u0652\u0641\u064e\u0639\u064f \u0644\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0645\u064e\u062a\u064e\u0627\u0639\u064e\u0647\u064f \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0648\u064e\u0627\u0644\u0652\u0643\u064e\u0644\u0650\u0645\u064e\u0629\u064f \u0627\u0644\u0637\u064e\u0651\u064a\u0650\u0651\u0628\u064e\u0629\u064f \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0648\u064e\u0628\u0650\u0643\u064f\u0644\u0650\u0651 \u062e\u064f\u0637\u0652\u0648\u064e\u0629\u064d \u062a\u064e\u0645\u0652\u0634\u0650\u064a\u0647\u064e\u0627 \u0625\u0644\u064e\u0649 \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u0650 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c\u060c \u0648\u064e\u062a\u064f\u0645\u0650\u064a\u0637\u064f \u0627\u0644\u0652\u0623\u064e\u0630\u064e\u0649 \u0639\u064e\u0646\u0652 \u0627\u0644\u0637\u064e\u0651\u0631\u0650\u064a\u0642\u0650 \u0635\u064e\u062f\u064e\u0642\u064e\u0629\u064c .<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0648\u064e\u0651\u0627\u0633\u0650 \u0628\u0652\u0646\u0650 \u0633\u064e\u0645\u0652\u0639\u064e\u0627\u0646\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0639\u064e\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \"\u0627\u0644\u0652\u0628\u0650\u0631\u064f\u0651 \u062d\u064f\u0633\u0652\u0646\u064f \u0627\u0644\u0652\u062e\u064f\u0644\u064f\u0642\u0650\u060c \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u064f \u0645\u064e\u0627 \u062d\u064e\u0627\u0643\u064e \u0641\u0650\u064a \u0635\u064e\u062f\u0652\u0631\u0650\u0643\u060c \u0648\u064e\u0643\u064e\u0631\u0650\u0647\u0652\u062a \u0623\u064e\u0646\u0652 \u064a\u064e\u0637\u064e\u0651\u0644\u0650\u0639\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f\" \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]. \u0648\u064e\u0639\u064e\u0646\u0652 \u0648\u064e\u0627\u0628\u0650\u0635\u064e\u0629\u064e \u0628\u0652\u0646\u0650 \u0645\u064e\u0639\u0652\u0628\u064e\u062f\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u062a\u064e\u064a\u0652\u062a \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0641\u064e\u0642\u064e\u0627\u0644\u064e: \"\u062c\u0650\u0626\u0652\u062a\u064e \u062a\u064e\u0633\u0652\u0623\u064e\u0644\u064f \u0639\u064e\u0646\u0652 \u0627\u0644\u0652\u0628\u0650\u0631\u0650\u0651\u061f \u0642\u064f\u0644\u0652\u062a: \u0646\u064e\u0639\u064e\u0645\u0652. \u0641\u0642\u064e\u0627\u0644\u064e: \u0627\u0633\u062a\u0641\u062a \u0642\u0644\u0628\u0643\u060c \u0627\u0644\u0652\u0628\u0650\u0631\u064f\u0651 \u0645\u064e\u0627 \u0627\u0637\u0652\u0645\u064e\u0623\u064e\u0646\u064e\u0651\u062a\u0652 \u0625\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0646\u064e\u0651\u0641\u0652\u0633\u064f\u060c \u0648\u064e\u0627\u0637\u0652\u0645\u064e\u0623\u064e\u0646\u064e\u0651 \u0625\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u0642\u064e\u0644\u0652\u0628\u064f\u060c \u0648\u064e\u0627\u0644\u0652\u0625\u0650\u062b\u0652\u0645\u064f \u0645\u064e\u0627 \u062d\u064e\u0627\u0643\u064e \u0641\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0641\u0652\u0633\u0650 \u0648\u064e\u062a\u064e\u0631\u064e\u062f\u064e\u0651\u062f\u064e \u0641\u0650\u064a \u0627\u0644\u0635\u064e\u0651\u062f\u0652\u0631\u0650\u060c \u0648\u064e\u0625\u0650\u0646\u0652 \u0623\u064e\u0641\u0652\u062a\u064e\u0627\u0643 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f \u0648\u064e\u0623\u064e\u0641\u0652\u062a\u064e\u0648\u0652\u0643\" . \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0631\u064e\u0648\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u064a \u0645\u064f\u0633\u0652\u0646\u064e\u062f\u064e\u064a \u0627\u0644\u0652\u0625\u0650\u0645\u064e\u0627\u0645\u064e\u064a\u0652\u0646\u0650 \u0623\u064e\u062d\u0652\u0645\u064e\u062f\u064e \u0628\u0652\u0646\u0650 \u062d\u064e\u0646\u0652\u0628\u064e\u0644\u064d [\u0631\u0642\u0645:4/227]\u060c \u0648\u064e\u0627\u0644\u062f\u064e\u0651\u0627\u0631\u0650\u0645\u0650\u064a\u0651 [2/246] \u0628\u0650\u0625\u0650\u0633\u0652\u0646\u064e\u0627\u062f\u064d \u062d\u064e\u0633\u064e\u0646\u064d", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0646\u064e\u062c\u0650\u064a\u062d\u064d \u0627\u0644\u0652\u0639\u0650\u0631\u0652\u0628\u064e\u0627\u0636\u0650 \u0628\u0652\u0646\u0650 \u0633\u064e\u0627\u0631\u0650\u064a\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0648\u064e\u0639\u064e\u0638\u064e\u0646\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064b \u0648\u064e\u062c\u0650\u0644\u064e\u062a\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0642\u064f\u0644\u064f\u0648\u0628\u064f\u060c \u0648\u064e\u0630\u064e\u0631\u064e\u0641\u064e\u062a\u0652 \u0645\u0650\u0646\u0652\u0647\u064e\u0627 \u0627\u0644\u0652\u0639\u064f\u064a\u064f\u0648\u0646\u064f\u060c \u0641\u064e\u0642\u064f\u0644\u0652\u0646\u064e\u0627: \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650! \u0643\u064e\u0623\u064e\u0646\u064e\u0651\u0647\u064e\u0627 \u0645\u064e\u0648\u0652\u0639\u0650\u0638\u064e\u0629\u064f \u0645\u064f\u0648\u064e\u062f\u0650\u0651\u0639\u064d \u0641\u064e\u0623\u064e\u0648\u0652\u0635\u0650\u0646\u064e\u0627\u060c \u0642\u064e\u0627\u0644\u064e: \u0623\u064f\u0648\u0635\u0650\u064a\u0643\u064f\u0645\u0652 \u0628\u0650\u062a\u064e\u0642\u0652\u0648\u064e\u0649 \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u0627\u0644\u0633\u064e\u0651\u0645\u0652\u0639\u0650 \u0648\u064e\u0627\u0644\u0637\u064e\u0651\u0627\u0639\u064e\u0629\u0650 \u0648\u064e\u0625\u0650\u0646\u0652 \u062a\u064e\u0623\u064e\u0645\u064e\u0651\u0631\u064e \u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0628\u0652\u062f\u064c\u060c \u0641\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064e\u0639\u0650\u0634\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0633\u064e\u064a\u064e\u0631\u064e\u0649 \u0627\u062e\u0652\u062a\u0650\u0644\u064e\u0627\u0641\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627\u060c \u0641\u064e\u0639\u064e\u0644\u064e\u064a\u0652\u0643\u064f\u0645\u0652 \u0628\u0650\u0633\u064f\u0646\u064e\u0651\u062a\u0650\u064a \u0648\u064e\u0633\u064f\u0646\u064e\u0651\u0629\u0650 \u0627\u0644\u0652\u062e\u064f\u0644\u064e\u0641\u064e\u0627\u0621\u0650 \u0627\u0644\u0631\u064e\u0651\u0627\u0634\u0650\u062f\u0650\u064a\u0646\u064e \u0627\u0644\u0652\u0645\u064e\u0647\u0652\u062f\u0650\u064a\u064a\u0646\u064e\u060c \u0639\u064e\u0636\u064f\u0651\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u064e\u0627 \u0628\u0650\u0627\u0644\u0646\u064e\u0651\u0648\u064e\u0627\u062c\u0650\u0630\u0650\u060c \u0648\u064e\u0625\u0650\u064a\u064e\u0651\u0627\u0643\u064f\u0645\u0652 \u0648\u064e\u0645\u064f\u062d\u0652\u062f\u064e\u062b\u064e\u0627\u062a\u0650 \u0627\u0644\u0652\u0623\u064f\u0645\u064f\u0648\u0631\u0650\u061b \u0641\u064e\u0625\u0650\u0646\u064e\u0651 \u0643\u064f\u0644\u064e\u0651 \u0628\u0650\u062f\u0652\u0639\u064e\u0629\u064d \u0636\u064e\u0644\u064e\u0627\u0644\u064e\u0629\u064c . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0623\u064e\u0628\u064f\u0648 \u062f\u064e\u0627\u0648\u064f\u062f\u064e]\u060c \u0648\u064e\u0627\u064e\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:266] \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c", "\u0639\u064e\u0646\u0652 \u0645\u064f\u0639\u064e\u0627\u0630\u0650 \u0628\u0652\u0646\u0650 \u062c\u064e\u0628\u064e\u0644\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064f\u0644\u0652\u062a \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650! \u0623\u064e\u062e\u0652\u0628\u0650\u0631\u0652\u0646\u0650\u064a \u0628\u0650\u0639\u064e\u0645\u064e\u0644\u064d \u064a\u064f\u062f\u0652\u062e\u0650\u0644\u064f\u0646\u0650\u064a \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u064e \u0648\u064e\u064a\u064f\u0628\u064e\u0627\u0639\u0650\u062f\u0652\u0646\u0650\u064a \u0645\u0650\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u0650\u060c \u0642\u064e\u0627\u0644\u064e: \"\u0644\u064e\u0642\u064e\u062f\u0652 \u0633\u064e\u0623\u064e\u0644\u0652\u062a \u0639\u064e\u0646\u0652 \u0639\u064e\u0638\u0650\u064a\u0645\u064d\u060c \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0647\u064f \u0644\u064e\u064a\u064e\u0633\u0650\u064a\u0631\u064c \u0639\u064e\u0644\u064e\u0649 \u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u064e\u0651\u0631\u064e\u0647\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650: \u062a\u064e\u0639\u0652\u0628\u064f\u062f\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0647\u0650 \u0634\u064e\u064a\u0652\u0626\u064b\u0627\u060c \u0648\u064e\u062a\u064f\u0642\u0650\u064a\u0645\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064e\u060c \u0648\u064e\u062a\u064f\u0624\u0652\u062a\u0650\u064a \u0627\u0644\u0632\u064e\u0651\u0643\u064e\u0627\u0629\u064e\u060c \u0648\u064e\u062a\u064e\u0635\u064f\u0648\u0645\u064f \u0631\u064e\u0645\u064e\u0636\u064e\u0627\u0646\u064e\u060c \u0648\u064e\u062a\u064e\u062d\u064f\u062c\u064f\u0651 \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u062a\u064e\u060c \u062b\u064f\u0645\u064e\u0651 \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0644\u064e\u0627 \u0623\u064e\u062f\u064f\u0644\u064f\u0651\u0643 \u0639\u064e\u0644\u064e\u0649 \u0623\u064e\u0628\u0652\u0648\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u062e\u064e\u064a\u0652\u0631\u0650\u061f \u0627\u0644\u0635\u064e\u0651\u0648\u0652\u0645\u064f \u062c\u064f\u0646\u064e\u0651\u0629\u064c\u060c \u0648\u064e\u0627\u0644\u0635\u064e\u0651\u062f\u064e\u0642\u064e\u0629\u064f \u062a\u064f\u0637\u0652\u0641\u0650\u0626\u064f \u0627\u0644\u0652\u062e\u064e\u0637\u0650\u064a\u0626\u064e\u0629\u064e \u0643\u064e\u0645\u064e\u0627 \u064a\u064f\u0637\u0652\u0641\u0650\u0626\u064f \u0627\u0644\u0652\u0645\u064e\u0627\u0621\u064f \u0627\u0644\u0646\u064e\u0651\u0627\u0631\u064e\u060c \u0648\u064e\u0635\u064e\u0644\u064e\u0627\u0629\u064f \u0627\u0644\u0631\u064e\u0651\u062c\u064f\u0644\u0650 \u0641\u0650\u064a \u062c\u064e\u0648\u0652\u0641\u0650 \u0627\u0644\u0644\u064e\u0651\u064a\u0652\u0644\u0650\u060c \u062b\u064f\u0645\u064e\u0651 \u062a\u064e\u0644\u064e\u0627: \" \u062a\u064e\u062a\u064e\u062c\u064e\u0627\u0641\u064e\u0649 \u062c\u064f\u0646\u064f\u0648\u0628\u064f\u0647\u064f\u0645\u0652 \u0639\u064e\u0646\u0650 \u0627\u0644\u0652\u0645\u064e\u0636\u064e\u0627\u062c\u0650\u0639\u0650 \" \u062d\u064e\u062a\u064e\u0651\u0649 \u0628\u064e\u0644\u064e\u063a\u064e \"\u064a\u064e\u0639\u0652\u0645\u064e\u0644\u064f\u0648\u0646\u064e\"\u060c[ 32 \u0633\u0648\u0631\u0629 \u0627\u0644\u0633\u062c\u062f\u0629 / \u0627\u0644\u0623\u064a\u062a\u0627\u0646 : 16 \u0648 17 ] \u062b\u064f\u0645\u064e\u0651 \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0644\u064e\u0627 \u0623\u064f\u062e\u0652\u0628\u0650\u0631\u064f\u0643 \u0628\u0650\u0631\u064e\u0623\u0652\u0633\u0650 \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0648\u064e\u0639\u064e\u0645\u064f\u0648\u062f\u0650\u0647\u0650 \u0648\u064e\u0630\u064f\u0631\u0652\u0648\u064e\u0629\u0650 \u0633\u064e\u0646\u064e\u0627\u0645\u0650\u0647\u0650\u061f \u0642\u064f\u0644\u0652\u062a: \u0628\u064e\u0644\u064e\u0649 \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650. \u0642\u064e\u0627\u0644\u064e: \u0631\u064e\u0623\u0652\u0633\u064f \u0627\u0644\u0652\u0623\u064e\u0645\u0652\u0631\u0650 \u0627\u0644\u0652\u0625\u0650\u0633\u0652\u0644\u064e\u0627\u0645\u064f\u060c \u0648\u064e\u0639\u064e\u0645\u064f\u0648\u062f\u064f\u0647\u064f \u0627\u0644\u0635\u064e\u0651\u0644\u064e\u0627\u0629\u064f\u060c \u0648\u064e\u0630\u064f\u0631\u0652\u0648\u064e\u0629\u064f \u0633\u064e\u0646\u064e\u0627\u0645\u0650\u0647\u0650 \u0627\u0644\u0652\u062c\u0650\u0647\u064e\u0627\u062f\u064f\u060c \u062b\u064f\u0645\u064e\u0651 \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u0644\u064e\u0627 \u0623\u064f\u062e\u0652\u0628\u0650\u0631\u064f\u0643 \u0628\u0650\u0645\u064e\u0644\u064e\u0627\u0643\u0650 \u0630\u064e\u0644\u0650\u0643\u064e \u0643\u064f\u0644\u0650\u0651\u0647\u0650\u061f \u0641\u0642\u064f\u0644\u0652\u062a: \u0628\u064e\u0644\u064e\u0649 \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 ! \u0641\u064e\u0623\u064e\u062e\u064e\u0630\u064e \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0647\u0650 \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u0643\u064f\u0641\u064e\u0651 \u0639\u064e\u0644\u064e\u064a\u0652\u0643 \u0647\u064e\u0630\u064e\u0627. \u0642\u064f\u0644\u0652\u062a: \u064a\u064e\u0627 \u0646\u064e\u0628\u0650\u064a\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0648\u064e\u0625\u0650\u0646\u064e\u0651\u0627 \u0644\u064e\u0645\u064f\u0624\u064e\u0627\u062e\u064e\u0630\u064f\u0648\u0646\u064e \u0628\u0650\u0645\u064e\u0627 \u0646\u064e\u062a\u064e\u0643\u064e\u0644\u064e\u0651\u0645\u064f \u0628\u0650\u0647\u0650\u061f \u0641\u064e\u0642\u064e\u0627\u0644\u064e: \u062b\u064e\u0643\u0650\u0644\u064e\u062a\u0652\u0643 \u0623\u064f\u0645\u064f\u0651\u0643 \u0648\u064e\u0647\u064e\u0644\u0652 \u064a\u064e\u0643\u064f\u0628\u064f\u0651 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064e \u0639\u064e\u0644\u064e\u0649 \u0648\u064f\u062c\u064f\u0648\u0647\u0650\u0647\u0650\u0645\u0652 -\u0623\u064e\u0648\u0652 \u0642\u064e\u0627\u0644\u064e \u0639\u064e\u0644\u064e\u0649 \u0645\u064e\u0646\u064e\u0627\u062e\u0650\u0631\u0650\u0647\u0650\u0645\u0652- \u0625\u0644\u064e\u0651\u0627 \u062d\u064e\u0635\u064e\u0627\u0626\u0650\u062f\u064f \u0623\u064e\u0644\u0652\u0633\u0650\u0646\u064e\u062a\u0650\u0647\u0650\u0645\u0652\u061f!\" . \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:2616] \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u062b\u064e\u0639\u0652\u0644\u064e\u0628\u064e\u0629\u064e \u0627\u0644\u0652\u062e\u064f\u0634\u064e\u0646\u0650\u064a\u0650\u0651 \u062c\u064f\u0631\u0652\u062b\u064f\u0648\u0645\u0650 \u0628\u0646 \u0646\u064e\u0627\u0634\u0650\u0631 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0639\u064e\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644: \"\u0625\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0641\u064e\u0631\u064e\u0636\u064e \u0641\u064e\u0631\u064e\u0627\u0626\u0650\u0636\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064f\u0636\u064e\u064a\u0650\u0651\u0639\u064f\u0648\u0647\u064e\u0627\u060c \u0648\u064e\u062d\u064e\u062f\u064e\u0651 \u062d\u064f\u062f\u064f\u0648\u062f\u064b\u0627 \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062a\u064e\u062f\u064f\u0648\u0647\u064e\u0627\u060c \u0648\u064e\u062d\u064e\u0631\u064e\u0651\u0645\u064e \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u062a\u064e\u0647\u0650\u0643\u064f\u0648\u0647\u064e\u0627\u060c \u0648\u064e\u0633\u064e\u0643\u064e\u062a\u064e \u0639\u064e\u0646\u0652 \u0623\u064e\u0634\u0652\u064a\u064e\u0627\u0621\u064e \u0631\u064e\u062d\u0652\u0645\u064e\u0629\u064b \u0644\u064e\u0643\u064f\u0645\u0652 \u063a\u064e\u064a\u0652\u0631\u064e \u0646\u0650\u0633\u0652\u064a\u064e\u0627\u0646\u064d \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u0652\u062d\u064e\u062b\u064f\u0648\u0627 \u0639\u064e\u0646\u0652\u0647\u064e\u0627\". \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062f\u064e\u0651\u0627\u0631\u064e\u0642\u064f\u0637\u0652\u0646\u0650\u064a\u0651 \u0652\"\u0641\u064a \u0633\u0646\u0646\u0647\" [4/184]\u060c \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0627\u0644\u0652\u0639\u064e\u0628\u064e\u0651\u0627\u0633\u0650 \u0633\u064e\u0647\u0652\u0644\u0650 \u0628\u0652\u0646\u0650 \u0633\u064e\u0639\u0652\u062f\u064d \u0627\u0644\u0633\u064e\u0651\u0627\u0639\u0650\u062f\u0650\u064a\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u062c\u064e\u0627\u0621\u064e \u0631\u064e\u062c\u064f\u0644\u064c \u0625\u0644\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0641\u064e\u0642\u064e\u0627\u0644\u064e: \u064a\u064e\u0627 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u0647\u0650! \u062f\u064f\u0644\u064e\u0651\u0646\u0650\u064a \u0639\u064e\u0644\u064e\u0649 \u0639\u064e\u0645\u064e\u0644\u064d \u0625\u0630\u064e\u0627 \u0639\u064e\u0645\u0650\u0644\u0652\u062a\u064f\u0647\u064f \u0623\u064e\u062d\u064e\u0628\u064e\u0651\u0646\u0650\u064a \u0627\u0644\u0644\u0647\u064f \u0648\u064e\u0623\u064e\u062d\u064e\u0628\u064e\u0651\u0646\u0650\u064a \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f\u061b \u0641\u064e\u0642\u064e\u0627\u0644\u064e: \u0627\u0632\u0652\u0647\u064e\u062f\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u064a\u064f\u062d\u0650\u0628\u0651\u064e\u0643 \u0627\u0644\u0644\u0647\u064f\u060c \u0648\u064e\u0627\u0632\u0652\u0647\u064e\u062f\u0652 \u0641\u0650\u064a\u0645\u064e\u0627 \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u0650 \u064a\u064f\u062d\u0650\u0628\u0651\u064e\u0643 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f . \u062d\u062f\u064a\u062b \u062d\u0633\u0646\u060c \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0627\u062c\u064e\u0647\u0652 [\u0631\u0642\u0645:4102]\u060c \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u0628\u0650\u0623\u064e\u0633\u064e\u0627\u0646\u0650\u064a\u062f\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064d", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0633\u064e\u0639\u0650\u064a\u062f\u064d \u0633\u064e\u0639\u0652\u062f\u0650 \u0628\u0652\u0646\u0650 \u0645\u064e\u0627\u0644\u0650\u0643\u0650 \u0628\u0652\u0646\u0650 \u0633\u0650\u0646\u064e\u0627\u0646\u064d \u0627\u0644\u0652\u062e\u064f\u062f\u0652\u0631\u0650\u064a\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0623\u064e\u0646\u064e\u0651 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \" \u0644\u064e\u0627 \u0636\u064e\u0631\u064e\u0631\u064e \u0648\u064e\u0644\u064e\u0627 \u0636\u0650\u0631\u064e\u0627\u0631\u064e\" . \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0627\u062c\u064e\u0647\u0652 [\u0631\u0627\u062c\u0639 \u0631\u0642\u0645:2341]\u060c \u0648\u064e\u0627\u0644\u062f\u064e\u0651\u0627\u0631\u064e\u0642\u064f\u0637\u0652\u0646\u0650\u064a\u0651 [\u0631\u0642\u0645:4/228]\u060c \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f\u0645\u064e\u0627 \u0645\u064f\u0633\u0652\u0646\u064e\u062f\u064b\u0627. \u0648\u064e\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064e\u0627\u0644\u0650\u0643\u064c [2/746] \u0641\u0650\u064a \"\u0627\u0644\u0652\u0645\u064f\u0648\u064e\u0637\u064e\u0651\u0625\u0650\" \u0639\u064e\u0646\u0652 \u0639\u064e\u0645\u0652\u0631\u0650\u0648 \u0628\u0652\u0646\u0650 \u064a\u064e\u062d\u0652\u064a\u064e\u0649 \u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a\u0647\u0650 \u0639\u064e\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0645\u064f\u0631\u0652\u0633\u064e\u0644\u064b\u0627\u060c \u0641\u064e\u0623\u064e\u0633\u0652\u0642\u064e\u0637\u064e \u0623\u064e\u0628\u064e\u0627 \u0633\u064e\u0639\u0650\u064a\u062f\u064d\u060c \u0648\u064e\u0644\u064e\u0647\u064f \u0637\u064f\u0631\u064f\u0642\u064c \u064a\u064f\u0642\u064e\u0648\u0650\u0651\u064a \u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064e\u0627 \u0628\u064e\u0639\u0652\u0636\u064b\u0627", "\u0639\u064e\u0646\u0652 \u0627\u0628\u0652\u0646\u0650 \u0639\u064e\u0628\u064e\u0651\u0627\u0633\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0651 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \"\u0644\u064e\u0648\u0652 \u064a\u064f\u0639\u0652\u0637\u064e\u0649 \u0627\u0644\u0646\u064e\u0651\u0627\u0633\u064f \u0628\u0650\u062f\u064e\u0639\u0652\u0648\u064e\u0627\u0647\u064f\u0645\u0652 \u0644\u064e\u0627\u062f\u064e\u0651\u0639\u064e\u0649 \u0631\u0650\u062c\u064e\u0627\u0644\u064c \u0623\u064e\u0645\u0652\u0648\u064e\u0627\u0644\u064e \u0642\u064e\u0648\u0652\u0645\u064d \u0648\u064e\u062f\u0650\u0645\u064e\u0627\u0621\u064e\u0647\u064f\u0645\u0652\u060c \u0644\u064e\u0643\u0650\u0646\u064e\u0651 \u0627\u0644\u0652\u0628\u064e\u064a\u0650\u0651\u0646\u064e\u0629\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u062f\u064e\u0651\u0639\u0650\u064a\u060c \u0648\u064e\u0627\u0644\u0652\u064a\u064e\u0645\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0645\u064e\u0646\u0652 \u0623\u064e\u0646\u0652\u0643\u064e\u0631\u064e\" . \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064e\u064a\u0652\u0647\u064e\u0642\u0650\u064a\u0651 [\u0641\u064a\"\u0627\u0644\u0633\u0646\u0646\" 10/252]\u060c \u0648\u064e\u063a\u064e\u064a\u0652\u0631\u064f\u0647\u064f \u0647\u064e\u0643\u064e\u0630\u064e\u0627\u060c \u0648\u064e\u0628\u064e\u0639\u0652\u0636\u064f\u0647\u064f \u0641\u0650\u064a \"\u0627\u0644\u0635\u064e\u0651\u062d\u0650\u064a\u062d\u064e\u064a\u0652\u0646\u0650", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0633\u064e\u0639\u0650\u064a\u062f\u064d \u0627\u0644\u0652\u062e\u064f\u062f\u0652\u0631\u0650\u064a\u0651 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e \u0633\u064e\u0645\u0650\u0639\u0652\u062a \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0645\u064e\u0646\u0652 \u0631\u064e\u0623\u064e\u0649 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0645\u064f\u0646\u0652\u0643\u064e\u0631\u064b\u0627 \u0641\u064e\u0644\u0652\u064a\u064f\u063a\u064e\u064a\u0650\u0651\u0631\u0652\u0647\u064f \u0628\u0650\u064a\u064e\u062f\u0650\u0647\u0650\u060c \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u0639\u0652 \u0641\u064e\u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0647\u0650\u060c \u0641\u064e\u0625\u0650\u0646\u0652 \u0644\u064e\u0645\u0652 \u064a\u064e\u0633\u0652\u062a\u064e\u0637\u0650\u0639\u0652 \u0641\u064e\u0628\u0650\u0642\u064e\u0644\u0652\u0628\u0650\u0647\u0650\u060c \u0648\u064e\u0630\u064e\u0644\u0650\u0643\u064e \u0623\u064e\u0636\u0652\u0639\u064e\u0641\u064f \u0627\u0644\u0652\u0625\u0650\u064a\u0645\u064e\u0627\u0646\u0650 . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0644\u064e\u0627 \u062a\u064e\u062d\u064e\u0627\u0633\u064e\u062f\u064f\u0648\u0627\u060c \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u064e\u0627\u062c\u064e\u0634\u064f\u0648\u0627\u060c \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0628\u064e\u0627\u063a\u064e\u0636\u064f\u0648\u0627\u060c \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u062f\u064e\u0627\u0628\u064e\u0631\u064f\u0648\u0627\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0628\u0650\u0639\u0652 \u0628\u064e\u0639\u0652\u0636\u064f\u0643\u064f\u0645\u0652 \u0639\u064e\u0644\u064e\u0649 \u0628\u064e\u064a\u0652\u0639\u0650 \u0628\u064e\u0639\u0652\u0636\u064d\u060c \u0648\u064e\u0643\u064f\u0648\u0646\u064f\u0648\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0625\u062e\u0652\u0648\u064e\u0627\u0646\u064b\u0627\u060c \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064f \u0623\u064e\u062e\u064f\u0648 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650\u060c \u0644\u064e\u0627 \u064a\u064e\u0638\u0652\u0644\u0650\u0645\u064f\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062e\u0652\u0630\u064f\u0644\u064f\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0643\u0652\u0630\u0650\u0628\u064f\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u062d\u0652\u0642\u0650\u0631\u064f\u0647\u064f\u060c \u0627\u0644\u062a\u064e\u0651\u0642\u0652\u0648\u064e\u0649 \u0647\u064e\u0627\u0647\u064f\u0646\u064e\u0627\u060c \u0648\u064e\u064a\u064f\u0634\u0650\u064a\u0631\u064f \u0625\u0644\u064e\u0649 \u0635\u064e\u062f\u0652\u0631\u0650\u0647\u0650 \u062b\u064e\u0644\u064e\u0627\u062b\u064e \u0645\u064e\u0631\u064e\u0651\u0627\u062a\u064d\u060c \u0628\u0650\u062d\u064e\u0633\u0652\u0628\u0650 \u0627\u0645\u0652\u0631\u0650\u0626\u064d \u0645\u0650\u0646\u0652 \u0627\u0644\u0634\u064e\u0651\u0631\u0650\u0651 \u0623\u064e\u0646\u0652 \u064a\u064e\u062d\u0652\u0642\u0650\u0631\u064e \u0623\u064e\u062e\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064e\u060c \u0643\u064f\u0644\u064f\u0651 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650 \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0650 \u062d\u064e\u0631\u064e\u0627\u0645\u064c: \u062f\u064e\u0645\u064f\u0647\u064f \u0648\u064e\u0645\u064e\u0627\u0644\u064f\u0647\u064f \u0648\u064e\u0639\u0650\u0631\u0652\u0636\u064f\u0647\u064f . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0639\u064e\u0646\u0652 \u0627\u0644\u0646\u064e\u0651\u0628\u0650\u064a\u0650\u0651 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \u0645\u064e\u0646\u0652 \u0646\u064e\u0641\u064e\u0651\u0633\u064e \u0639\u064e\u0646\u0652 \u0645\u064f\u0624\u0652\u0645\u0650\u0646\u064d \u0643\u064f\u0631\u0652\u0628\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0643\u064f\u0631\u064e\u0628\u0650 \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0646\u064e\u0641\u064e\u0651\u0633\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0643\u064f\u0631\u0652\u0628\u064e\u0629\u064b \u0645\u0650\u0646\u0652 \u0643\u064f\u0631\u064e\u0628\u0650 \u064a\u064e\u0648\u0652\u0645\u0650 \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0633\u064e\u0651\u0631\u064e \u0639\u064e\u0644\u064e\u0649 \u0645\u064f\u0639\u0652\u0633\u0650\u0631\u064d\u060c \u064a\u064e\u0633\u064e\u0651\u0631\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0633\u064e\u062a\u064e\u0631\u064e \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u0627 \u0633\u064e\u062a\u064e\u0631\u064e\u0647\u064f \u0627\u0644\u0644\u0647\u064f \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0652\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u060c \u0648\u064e\u0627\u064e\u0644\u0644\u064e\u0651\u0647\u064f \u0641\u0650\u064a \u0639\u064e\u0648\u0652\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u0650 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0627\u0644\u0652\u0639\u064e\u0628\u0652\u062f\u064f \u0641\u0650\u064a \u0639\u064e\u0648\u0652\u0646\u0650 \u0623\u064e\u062e\u0650\u064a\u0647\u0650\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0633\u064e\u0644\u064e\u0643\u064e \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u064a\u064e\u0644\u0652\u062a\u064e\u0645\u0650\u0633\u064f \u0641\u0650\u064a\u0647\u0650 \u0639\u0650\u0644\u0652\u0645\u064b\u0627 \u0633\u064e\u0647\u064e\u0651\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0644\u064e\u0647\u064f \u0628\u0650\u0647\u0650 \u0637\u064e\u0631\u0650\u064a\u0642\u064b\u0627 \u0625\u0644\u064e\u0649 \u0627\u0644\u0652\u062c\u064e\u0646\u064e\u0651\u0629\u0650\u060c \u0648\u064e\u0645\u064e\u0627 \u0627\u062c\u0652\u062a\u064e\u0645\u064e\u0639\u064e \u0642\u064e\u0648\u0652\u0645\u064c \u0641\u0650\u064a \u0628\u064e\u064a\u0652\u062a\u064d \u0645\u0650\u0646\u0652 \u0628\u064f\u064a\u064f\u0648\u062a\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u064a\u064e\u062a\u0652\u0644\u064f\u0648\u0646\u064e \u0643\u0650\u062a\u064e\u0627\u0628\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650\u060c \u0648\u064e\u064a\u064e\u062a\u064e\u062f\u064e\u0627\u0631\u064e\u0633\u064f\u0648\u0646\u064e\u0647\u064f \u0641\u0650\u064a\u0645\u064e\u0627 \u0628\u064e\u064a\u0652\u0646\u064e\u0647\u064f\u0645\u0652\u061b \u0625\u0644\u064e\u0651\u0627 \u0646\u064e\u0632\u064e\u0644\u064e\u062a\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0627\u0644\u0633\u064e\u0651\u0643\u0650\u064a\u0646\u064e\u0629\u064f\u060c \u0648\u064e\u063a\u064e\u0634\u0650\u064a\u064e\u062a\u0652\u0647\u064f\u0645\u0652 \u0627\u0644\u0631\u064e\u0651\u062d\u0652\u0645\u064e\u0629\u064f\u060c \u0648\u064e \u062d\u064e\u0641\u064e\u0651\u062a\u0647\u064f\u0645\u064f \u0627\u0644\u0645\u064e\u0644\u0627\u064e\u0626\u0650\u0643\u064e\u0629\u060c \u0648\u064e\u0630\u064e\u0643\u064e\u0631\u064e\u0647\u064f\u0645\u0652 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0641\u0650\u064a\u0645\u064e\u0646\u0652 \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f\u060c \u0648\u064e\u0645\u064e\u0646\u0652 \u0623\u064e\u0628\u064e\u0637\u0652\u0623\u064e \u0628\u0650\u0647\u0650 \u0639\u064e\u0645\u064e\u0644\u064f\u0647\u064f \u0644\u064e\u0645\u0652 \u064a\u064f\u0633\u0652\u0631\u0650\u0639\u0652 \u0628\u0650\u0647\u0650 \u0646\u064e\u0633\u064e\u0628\u064f\u0647\u064f . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c] \u0628\u0647\u0630\u0627 \u0627\u0644\u0644\u0641\u0638", "\u0639\u064e\u0646\u0652 \u0627\u0628\u0652\u0646\u0650 \u0639\u064e\u0628\u064e\u0651\u0627\u0633\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0639\u064e\u0646\u0652 \u0631\u064e\u0633\u064f\u0648\u0644\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0641\u0650\u064a\u0645\u064e\u0627 \u064a\u064e\u0631\u0652\u0648\u0650\u064a\u0647\u0650 \u0639\u064e\u0646\u0652 \u0631\u064e\u0628\u0650\u0651\u0647\u0650 \u062a\u064e\u0628\u064e\u0627\u0631\u064e\u0643\u064e \u0648\u064e\u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649\u060c \u0642\u064e\u0627\u0644\u064e: \"\u0625\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u0643\u064e\u062a\u064e\u0628\u064e \u0627\u0644\u0652\u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0633\u064e\u0651\u064a\u0650\u0651\u0626\u064e\u0627\u062a\u0650\u060c \u062b\u064f\u0645\u064e\u0651 \u0628\u064e\u064a\u064e\u0651\u0646\u064e \u0630\u064e\u0644\u0650\u0643\u064e\u060c \u0641\u064e\u0645\u064e\u0646\u0652 \u0647\u064e\u0645\u064e\u0651 \u0628\u0650\u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064d \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652\u0647\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u064b\u060c \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0651 \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0639\u064e\u0645\u0650\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u0639\u064e\u0634\u0652\u0631\u064e \u062d\u064e\u0633\u064e\u0646\u064e\u0627\u062a\u064d \u0625\u0644\u064e\u0649 \u0633\u064e\u0628\u0652\u0639\u0650\u0645\u0650\u0627\u0626\u064e\u0629\u0650 \u0636\u0650\u0639\u0652\u0641\u064d \u0625\u0644\u064e\u0649 \u0623\u064e\u0636\u0652\u0639\u064e\u0627\u0641\u064d \u0643\u064e\u062b\u0650\u064a\u0631\u064e\u0629\u064d\u060c \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0651 \u0628\u0650\u0633\u064e\u064a\u0650\u0651\u0626\u064e\u0629\u064d \u0641\u064e\u0644\u064e\u0645\u0652 \u064a\u064e\u0639\u0652\u0645\u064e\u0644\u0652\u0647\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u0650\u0646\u0652\u062f\u064e\u0647\u064f \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0643\u064e\u0627\u0645\u0650\u0644\u064e\u0629\u064b\u060c \u0648\u064e\u0625\u0650\u0646\u0652 \u0647\u064e\u0645\u064e\u0651 \u0628\u0650\u0647\u064e\u0627 \u0641\u064e\u0639\u064e\u0645\u0650\u0644\u064e\u0647\u064e\u0627 \u0643\u064e\u062a\u064e\u0628\u064e\u0647\u064e\u0627 \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0633\u064e\u064a\u0650\u0651\u0626\u064e\u0629\u064b \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064b\".<br>[\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651] \u060c [\u0648\u064e\u0645\u064f\u0633\u0652\u0644\u0650\u0645\u064c]\u060c \u0641\u064a \"\u0635\u062d\u064a\u062d\u064a\u0647\u0645\u0627\" \u0628\u0647\u0630\u0647 \u0627\u0644\u062d\u0631\u0648\u0641", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0647\u064f\u0631\u064e\u064a\u0652\u0631\u064e\u0629 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0625\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649 \u0642\u064e\u0627\u0644\u064e: \u0645\u064e\u0646\u0652 \u0639\u064e\u0627\u062f\u064e\u0649 \u0644\u0650\u064a \u0648\u064e\u0644\u0650\u064a\u064b\u0651\u0627 \u0641\u064e\u0642\u0652\u062f \u0622\u0630\u064e\u0646\u0652\u062a\u0647\u064f \u0628\u0650\u0627\u0644\u0652\u062d\u064e\u0631\u0652\u0628\u0650\u060c \u0648\u064e\u0645\u064e\u0627 \u062a\u064e\u0642\u064e\u0631\u064e\u0651\u0628\u064e \u0625\u0644\u064e\u064a\u064e\u0651 \u0639\u064e\u0628\u0652\u062f\u0650\u064a \u0628\u0650\u0634\u064e\u064a\u0652\u0621\u064d \u0623\u064e\u062d\u064e\u0628\u064e\u0651 \u0625\u0644\u064e\u064a\u064e\u0651 \u0645\u0650\u0645\u064e\u0651\u0627 \u0627\u0641\u0652\u062a\u064e\u0631\u064e\u0636\u0652\u062a\u064f\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u060c \u0648\u064e\u0644\u064e\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f \u0639\u064e\u0628\u0652\u062f\u0650\u064a \u064a\u064e\u062a\u064e\u0642\u064e\u0631\u064e\u0651\u0628\u064f \u0625\u0644\u064e\u064a\u064e\u0651 \u0628\u0650\u0627\u0644\u0646\u064e\u0651\u0648\u064e\u0627\u0641\u0650\u0644\u0650 \u062d\u064e\u062a\u064e\u0651\u0649 \u0623\u064f\u062d\u0650\u0628\u064e\u0651\u0647\u064f\u060c \u0641\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u062d\u0652\u0628\u064e\u0628\u0652\u062a\u064f\u0647\u064f \u0643\u064f\u0646\u0652\u062a \u0633\u064e\u0645\u0652\u0639\u064e\u0647\u064f \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u064a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0628\u0650\u0647\u0650\u060c \u0648\u064e\u0628\u064e\u0635\u064e\u0631\u064e\u0647\u064f \u0627\u0644\u064e\u0651\u0630\u0650\u064a \u064a\u064f\u0628\u0652\u0635\u0650\u0631\u064f \u0628\u0650\u0647\u0650\u060c \u0648\u064e\u064a\u064e\u062f\u064e\u0647\u064f \u0627\u0644\u064e\u0651\u062a\u0650\u064a \u064a\u064e\u0628\u0652\u0637\u0650\u0634\u064f \u0628\u0650\u0647\u064e\u0627\u060c \u0648\u064e\u0631\u0650\u062c\u0652\u0644\u064e\u0647\u064f \u0627\u0644\u064e\u0651\u062a\u0650\u064a \u064a\u064e\u0645\u0652\u0634\u0650\u064a \u0628\u0650\u0647\u064e\u0627\u060c \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0633\u064e\u0623\u064e\u0644\u064e\u0646\u0650\u064a \u0644\u064e\u0623\u064f\u0639\u0652\u0637\u0650\u064a\u064e\u0646\u064e\u0651\u0647\u064f\u060c \u0648\u064e\u0644\u064e\u0626\u0650\u0646\u0652 \u0627\u0633\u0652\u062a\u064e\u0639\u064e\u0627\u0630\u064e\u0646\u0650\u064a \u0644\u064e\u0623\u064f\u0639\u0650\u064a\u0630\u064e\u0646\u064e\u0651\u0647\u064f . [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651]", "\u0639\u064e\u0646\u0652 \u0627\u0628\u0652\u0646\u0650 \u0639\u064e\u0628\u064e\u0651\u0627\u0633\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0623\u064e\u0646\u064e\u0651 \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0642\u064e\u0627\u0644\u064e: \"\u0625\u0646\u064e\u0651 \u0627\u0644\u0644\u064e\u0651\u0647\u064e \u062a\u064e\u062c\u064e\u0627\u0648\u064e\u0632\u064e \u0644\u0650\u064a \u0639\u064e\u0646\u0652 \u0623\u064f\u0645\u064e\u0651\u062a\u0650\u064a \u0627\u0644\u0652\u062e\u064e\u0637\u064e\u0623\u064e \u0648\u064e\u0627\u0644\u0646\u0650\u0651\u0633\u0652\u064a\u064e\u0627\u0646\u064e \u0648\u064e\u0645\u064e\u0627 \u0627\u0633\u0652\u062a\u064f\u0643\u0652\u0631\u0650\u0647\u064f\u0648\u0627 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\" . \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c\u060c \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0628\u0652\u0646\u064f \u0645\u064e\u0627\u062c\u064e\u0647\u0652 [\u0631\u0642\u0645:2045]\u060c \u0648\u064e\u0627\u0644\u0652\u0628\u064e\u064a\u0652\u0647\u064e\u0642\u0650\u064a\u0651 [\"\u0627\u0644\u0633\u0646\u0646]", "\u0639\u064e\u0646\u0652 \u0627\u0628\u0652\u0646 \u0639\u064f\u0645\u064e\u0631\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u0642\u064e\u0627\u0644\u064e: \u0623\u064e\u062e\u064e\u0630\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u0628\u0650\u0645\u064e\u0646\u0652\u0643\u0650\u0628\u0650\u064a\u060c \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u0643\u064f\u0646\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u064f\u0651\u0646\u0652\u064a\u064e\u0627 \u0643\u064e\u0623\u064e\u0646\u064e\u0651\u0643 \u063a\u064e\u0631\u0650\u064a\u0628\u064c \u0623\u064e\u0648\u0652 \u0639\u064e\u0627\u0628\u0650\u0631\u064f \u0633\u064e\u0628\u0650\u064a\u0644\u064d . \u0648\u064e\u0643\u064e\u0627\u0646\u064e \u0627\u0628\u0652\u0646\u064f \u0639\u064f\u0645\u064e\u0631\u064e \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0625\u0630\u064e\u0627 \u0623\u064e\u0645\u0652\u0633\u064e\u064a\u0652\u062a\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u0652 \u0627\u0644\u0635\u064e\u0651\u0628\u064e\u0627\u062d\u064e\u060c \u0648\u064e\u0625\u0650\u0630\u064e\u0627 \u0623\u064e\u0635\u0652\u0628\u064e\u062d\u0652\u062a\u064e \u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0646\u0652\u062a\u064e\u0638\u0650\u0631\u0652 \u0627\u0644\u0652\u0645\u064e\u0633\u064e\u0627\u0621\u064e\u060c \u0648\u064e\u062e\u064f\u0630\u0652 \u0645\u0650\u0646\u0652 \u0635\u0650\u062d\u064e\u0651\u062a\u0650\u0643 \u0644\u0650\u0645\u064e\u0631\u064e\u0636\u0650\u0643\u060c \u0648\u064e\u0645\u0650\u0646\u0652 \u062d\u064e\u064a\u064e\u0627\u062a\u0650\u0643 \u0644\u0650\u0645\u064e\u0648\u0652\u062a\u0650\u0643. [\u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u0652\u0628\u064f\u062e\u064e\u0627\u0631\u0650\u064a\u064f\u0651]", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0628\u0650\u064a \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f\u064d \u0639\u064e\u0628\u0652\u062f\u0650 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0628\u0652\u0646\u0650 \u0639\u064e\u0645\u0652\u0631\u0650\u0648 \u0628\u0652\u0646\u0650 \u0627\u0644\u0652\u0639\u064e\u0627\u0635\u0650 \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f\u0645\u064e\u0627\u060c \u0642\u064e\u0627\u0644\u064e: \u0642\u064e\u0627\u0644\u064e \u0631\u064e\u0633\u064f\u0648\u0644\u064f \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \"\u0644\u064e\u0627 \u064a\u064f\u0624\u0652\u0645\u0650\u0646\u064f \u0623\u064e\u062d\u064e\u062f\u064f\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u064e\u0651\u0649 \u064a\u064e\u0643\u064f\u0648\u0646\u064e \u0647\u064e\u0648\u064e\u0627\u0647\u064f \u062a\u064e\u0628\u064e\u0639\u064b\u0627 \u0644\u0650\u0645\u064e\u0627 \u062c\u0650\u0626\u0652\u062a\u064f \u0628\u0650\u0647\u0650\". \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c\u060c \u0631\u064e\u0648\u064e\u064a\u0652\u0646\u064e\u0627\u0647\u064f \u0641\u0650\u064a \u0643\u0650\u062a\u064e\u0627\u0628\u0650 \"\u0627\u0644\u0652\u062d\u064f\u062c\u064e\u0651\u0629\u0650\" \u0628\u0650\u0625\u0650\u0633\u0652\u0646\u064e\u0627\u062f\u064d \u0635\u064e\u062d\u0650\u064a\u062d\u064d", "\u0639\u064e\u0646\u0652 \u0623\u064e\u0646\u064e\u0633\u0650 \u0628\u0652\u0646\u0650 \u0645\u064e\u0627\u0644\u0650\u0643\u064d \u0631\u064e\u0636\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u064e\u0646\u0652\u0647\u064f \u0642\u064e\u0627\u0644\u064e: \u0633\u064e\u0645\u0650\u0639\u0652\u062a \u0631\u064e\u0633\u064f\u0648\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648 \u0633\u0644\u0645 \u064a\u064e\u0642\u064f\u0648\u0644\u064f: \u0642\u064e\u0627\u0644\u064e \u0627\u0644\u0644\u064e\u0651\u0647\u064f \u062a\u064e\u0639\u064e\u0627\u0644\u064e\u0649: \u064a\u064e\u0627 \u0627\u0628\u0652\u0646\u064e \u0622\u062f\u064e\u0645\u064e! \u0625\u0650\u0646\u064e\u0651\u0643\u064e \u0645\u064e\u0627 \u062f\u064e\u0639\u064e\u0648\u0652\u062a\u0646\u0650\u064a \u0648\u064e\u0631\u064e\u062c\u064e\u0648\u0652\u062a\u0646\u0650\u064a \u063a\u064e\u0641\u064e\u0631\u0652\u062a\u064f \u0644\u064e\u0643 \u0639\u064e\u0644\u064e\u0649 \u0645\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0645\u0650\u0646\u0652\u0643 \u0648\u064e\u0644\u064e\u0627 \u0623\u064f\u0628\u064e\u0627\u0644\u0650\u064a\u060c \u064a\u064e\u0627 \u0627\u0628\u0652\u0646\u064e \u0622\u062f\u064e\u0645\u064e! \u0644\u064e\u0648\u0652 \u0628\u064e\u0644\u064e\u063a\u064e\u062a\u0652 \u0630\u064f\u0646\u064f\u0648\u0628\u064f\u0643 \u0639\u064e\u0646\u064e\u0627\u0646\u064e \u0627\u0644\u0633\u064e\u0651\u0645\u064e\u0627\u0621\u0650 \u062b\u064f\u0645\u064e\u0651 \u0627\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u064e\u0631\u0652\u062a\u0646\u0650\u064a \u063a\u064e\u0641\u064e\u0631\u0652\u062a\u064f \u0644\u064e\u0643\u060c \u064a\u064e\u0627 \u0627\u0628\u0652\u0646\u064e \u0622\u062f\u064e\u0645\u064e! \u0625\u0646\u064e\u0651\u0643 \u0644\u064e\u0648\u0652 \u0623\u062a\u064e\u064a\u0652\u062a\u0646\u0650\u064a \u0628\u0650\u0642\u064f\u0631\u064e\u0627\u0628\u0650 \u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u062e\u064e\u0637\u064e\u0627\u064a\u064e\u0627 \u062b\u064f\u0645\u064e\u0651 \u0644\u064e\u0642\u0650\u064a\u062a\u0646\u0650\u064a \u0644\u064e\u0627 \u062a\u064f\u0634\u0652\u0631\u0650\u0643\u064f \u0628\u0650\u064a \u0634\u064e\u064a\u0652\u0626\u064b\u0627 \u0644\u064e\u0623\u064e\u062a\u064e\u064a\u0652\u062a\u064f\u0643 \u0628\u0650\u0642\u064f\u0631\u064e\u0627\u0628\u0650\u0647\u064e\u0627 \u0645\u064e\u063a\u0652\u0641\u0650\u0631\u064e\u0629\u064b . \u0631\u064e\u0648\u064e\u0627\u0647\u064f \u0627\u0644\u062a\u0650\u0651\u0631\u0652\u0645\u0650\u0630\u0650\u064a\u064f\u0651 [\u0631\u0642\u0645:3540]\u060c \u0648\u064e\u0642\u064e\u0627\u0644\u064e: \u062d\u064e\u062f\u0650\u064a\u062b\u064c \u062d\u064e\u0633\u064e\u0646\u064c \u0635\u064e\u062d\u0650\u064a\u062d\u064c"];
